comms.text:
@1 וַאֲמַר יְיָ לְמֹשֶׁה אֱמַר לְכַהֲנַיָא בְּנֵי אַהֲרֹן וְתֵימַר לְהוֹן עַל מִית לָא יִסְתָּאַב בְּעַמֵהּ:
@2 אֱלָהֵן לְקָרִיבֵהּ דְקָרִיב לֵהּ לְאִמֵהּ וְלַאֲבוּהִי וְלִבְרֵהּ וְלִבְרַתֵּהּ וְלַאֲחוּהִי:
@3 וְלַאֲחָתֵהּ בְּתֻלְתָּא דְקָרִיבָא לֵהּ דִי לָא הֲוַת לִגְבַר לַהּ יִסְתָּאָב:
@4 לָא יִסְתָּאַב רַבָּא בְעַמֵהּ לְאַחֲלוּתֵהּ:
@5 לָא יִמְרְטוּן מְרַט בְּרֵישְׁהוֹן וּפָאתָא דְדִקְנְהוֹן לָא יְגַלְחוּן וּבְבִשְׂרְהוֹן לָא יְחַבְּלוּן חִבּוּל:
@6 קַדִישִׁין יְהוֹן קֳדָם אֱלָהֲהוֹן וְלָא יְחַלוּן שְׁמָא דֶאֱלָהֲהוֹן אֲרֵי יָת קֻרְבָּנַיָא דַיְיָ קֻרְבַּן אֱלָהֲהוֹן אִנוּן מַקְרִיבִין וִיהוֹן קַדִישִׁין:
@7 אִתְּתָא מַטְעֲיָא וּמְחַלְלָא לָא יִסְבוּן וְאִתְּתָא דִמְתָרְכָא מִבַּעְלַהּ לָא יִסְבוּן אֲרֵי קַדִישׁ הוּא קֳדָם אֱלָהֵהּ:
@8 וּתְקַדְשִׁנֵהּ אֲרֵי יָת קֻרְבַּן אֱלָהָךְ הוּא מְקָרֵב קַדִישׁ יְהֵא לָךְ אֲרֵי קַדִישׁ אֲנָא יְיָ מְקַדִשְׁכוֹן:
@9 וּבַת גְבַר כָּהֵן אֲרֵי תִתְחַל לְמִטְעֵי מִקְדֻשַׁת אֲבוּהָ הִיא מִתַּחֲלָא בְּנוּרָא תִּתּוֹקָד:
@10 וְכַהֲנָא דְאִתְרַבָּא מֵאֲחוֹהִי דְיִתָּרִיק עַל רֵישֵׁהּ מִשְׁחָא דִרְבוּתָא וְדִי קָרִיב יָת קֻרְבָּנֵהּ לְמִלְבָּשׁ יָת לְבוּשַׁיָא יָת רֵישֵׁהּ לָא יְרַבֵּי פֵרוּעַ וּלְבוּשׁוֹהִי לָא יִבְזַע:
@11 וְעַל כָּל נַפְשַׁת מֵתָא לָא יֵיעוֹל לַאֲבוּהִי וּלְאִמֵהּ לָא יִסְתָּאָב:
@12 וּמִן מַקְדְשָׁא לָא יִפּוֹק וְלָא יַחֵל יָת מַקְדְשָׁא דֶאֱלָהֵהּ אֲרֵי כְּלִיל מְשַׁח רְבוּתָא דֶאֱלָהֵהּ עֲלוֹהִי אֲנָא יְיָ:
@13 וְהוּא אִתְּתָא בִבְתֻלְתָּהָא יִסָב:
@14 אַרְמְלָא וּמְתָרְכָא וְחַלִילָא מַטְעֲיָא יָת אִלֵין לָא יִסָב אֱלָהֵין בְּתֻלְתָּא מֵעַמֵהּ יִסַב אִתְּתָא:
@15 וְלָא יַחֵל זַרְעֵהּ בְּעַמֵהּ אֲרֵי אֲנָא יְיָ מְקַדְשֵׁהּ:
@16 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@17 מַלֵל עִם אַהֲרֹן לְמֵימָר גְבַר מִבְּנָיִךְ לְדָרֵיהוֹן דִי יְהֵּי בֵהּ מוּמָא לָא יִקְרַב לְקָרָבָא קֻרְבָּנָא קֳדָם אֱלָהֵהּ:
@18 אֲרֵי כָל גְבַר דִּי בֵהּ מוּמָא לָא יִקְרַב גְבַר עַוִיר אוֹ חֲגִיר אוֹ חָרִים אוֹ שָׂרִיע:
@19 אוֹ גְבַר דִי יְהֵי בֵהּ תְּבַר רַגְלָא אוֹ תְּבַר יְדָא:
@20 אוֹ גְבִין אוֹ דֻקָא אוֹ חִלִיז בְּעֵינֵהּ אוֹ גַרְבָן אוֹ חֲזָזָן אוֹ מְרִיס פַּחֲדִין:
@21 כָּל גְבַר דִי בֵהּ מוּמָא מִזַרְעָא דְאַהֲרֹן כַּהֲנָא לָא יִקְרַב לְקָרָבָא יָת קֻרְבָּנַיָא דַיְיָ מוּמָא בֵהּ יָת קֻרְבַּן אֱלָהֵהּ לָא יִקְרַב לְקָרָבָא:
@22 קֻרְבַּן אֱלָהֵהּ מִקֹדֶשׁ קוּדְשַׁיָא וּמִן קוּדְשַׁיָא יֵיכוּל:
@23 בְּרַם לְפָרֻכְתָּא לָא יֵיעוֹל וּלְמַדְבְּחָא לָא יִקְרַב אֲרֵי מוּמָא בֵהּ וְלָא יַחֵל יָת מַקְדְשַׁי אֲרֵי אֲנָא יְיָ מְקַדִשְׁהוֹן:
@24 וּמַלִיל מֹשֶׁה עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל:
@25 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@26 מַלֵיל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְיִפָּרְשׁוּן מִקוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל וְלָא יְחַלוּן יָת שְׁמָא דְקוּדְשִׁי דִי אִנוּן מְקַדְשִׁין קֳדָמַי אֲנָא יְיָ:
@27 אֱמַר לְהוֹן לְדָרֵיכוֹן כָּל גְבַר דִי יִקְרַב מִכָּל בְּנֵיכוֹן לְקוּדְשַׁיָא דִי יְקַדְשׁוּן בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ וְסֹאבְתֵיהּ עֲלוֹהִי וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהִיא מִן קֳדָמַי אֲנָא יְיָ:
@28 גְבַר גְבַר מִזַרְעָא דְאַהֲרֹן וְהוּא סְגִיר אוֹ דָאִיב בְּקוּדְשַׁיָא לָא יֵיכוּל עַד דִי יִדְכֵּי וּדְיִקְרַב בְּכָל טְמֵא נַפְשָׁא אוֹ גְבַר דִי תִפּוֹק מִנֵהּ שִׁכְבַת זַרְעָא:
@29 אוֹ גְבַר דִי יִקְרַב בְּכָל רִחֲשָׁא דִי יִסְתָּאַב לֵהּ אוֹ בַאֲנָשָׁא דִי יִסְתָּאַב לֵהּ:לכָל סֹאבְתֵיהּ:
@30 אֱנַשׁ דִי יִקְרַב בֵּהּ וִיהֵי מְסָאָב עַד רַמְשָׁא וְלָא יֵיכוּל מִן קוּדְשַׁיָא אֱלָהֵן אַסְחֵי בִשׂרֵהּ בְּמַיָא:
@31 וּבְמֵעַל:שִׁמְשָׁא וְיִדְכֵּי וּבָתַר כֵּן יֵיכוּל מִן קוּדְשַׁיָא אֲרֵי לַחְמֵהּ הוּא:
@32 נְבִילָא וּתְבִירָא לָא יֵיכוּל לְאִסְתָּאָבָא בָהּ אֲנָא יְיָ:
@33 וְיִטְרוּן יָת מַטְּרַת מֵימְרִי וְלָא יְקַבְּלוּן עֲלוֹהִי חוֹבָא וִימוּתוּן בֵּהּ אֲרֵי יְחַלֻנֵהּ אֲנָא יְיָ מְקַדִשְׁהוֹן:
@34 וְכָל חִלוֹנַי לָא יֵיכוּל קוּדְשָׁא תּוֹתָבָא דְכַהֲנָא וַאֲגִירָא לָא יֵיכוּל קוּדְשָׁא:
@35 וְכָהֵן אֲרֵי יִקְנֵי נְפַשׁ קִנְיַן כַּסְפֵּהּ הוּא יֵיכוּל בֵּהּ וִילִיד בֵּיתֵהּ אִנוּן יֵיכְלוּן בְּלַחְמֵהּ:
@36 וּבַת כָּהֵן אֲרֵי תְהִי לִגְבַר חִלוֹנָי הִיא בְּאַפְרָשׁוּת קוּדְשַׁיָא לָא תֵיכוּל:
@37 וּבַת כָּהֵן אֲרֵי תְהֵי אַרְמְלָא וּמְתָרְכָא וּבַר לֵית לַהּ וּתְתוּב לְבֵית אֲבוּהָא כְּרַבְיוּתָהָא מִלַחְמָא דַאֲבוּהָא תֵּיכוּל וְכָל חִלוֹנַי לָא יֵיכוּל בֵּהּ:
@38 וּגְבַר אֲרֵי יֵיכוּל קוּדְשָׁא בְּשָׁלוּ וְיוֹסֵף חוּמְשֵׁהּ עֲלוֹהִי וְיִתֵּן לְכַהֲנָא יָת קוּדְשָׁא:
@39 וְלָא יְחַלוּן יָת קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל יָת דִי יַפְרְשׁוּן קֳדָם יְיָ:
@40 וִיקַבְּלוּן עֲלֵיהוֹן עֲוָיָן וְחוֹבִין בְּמֵיכָלְהוֹן בְּסוֹאֲבָא יָת קוּדְשֵׁיהוֹן אֲרֵי אֲנָא יְיָ מְקַדִשְׁהוֹן:
@41 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@42 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְבַר גְבַר מִבֵּית יִשְׂרָאֵל וּמִן גִיוֹרָא בְּיִשְׂרָאֵל דִי יְקָרֵב קֻרְבָּנֵהּ לְכָל נִדְרֵיהוֹן וּלְכָל נִדְבָתְהוֹן דִי יְקָרְבוּן קֳדָם יְיָ לַעֲלָתָא:
@43 לְרַעֲוָא לְכוֹן שְׁלִים דְכוּרָא בְּתוֹרֵי בְּאִמְרַיָא וּבְעִזַיָא:
@44 כֹּל דִי בֵהּ מוּמָא לָא תְקָרְבוּן אֲרֵי לָא לְרַעֲוָא יְהֵי לְכוֹן:
@45 וּגְבַר אֲרֵי יְקָרֵב נִכְסַת קוּדְשַׁיָא קֳדָם יְיָ לְפָרָשָׁא נִדְרָא אוֹ לִנְדַבְתָּא בְּתוֹרֵי אוֹ בְעָנָא שְׁלִים יְהֵי לְרַעֲוָא כָּל מוּמָא לָא יְהֵי בֵהּ:
@46 עַוִיר אוֹ תְבִיר אוֹ פְסִיק אוֹ יַבְּלָן אוֹ גַרְבָן אוֹ חֲזָזָן לָא תְקָרְבוּן אִלֵין קֳדָם יְיָ וְקֻרְבָּנָא לָא תִתְּנוּן מִנְהוֹן עַל מַדְבְּחָא קֳדָם יְיָ:
@47 וְתוֹר וְאִמַר יַתִּיר וְחַסִיר נְדַבְתָּא תַּעְבֵּד יָתֵהּ וּלְנִדְרָא לָא יְהֵי לְרַעֲוָא:
@48 וְדִי מְרִיס וְדִי רְסִיס וְדִי שְׁלִיף וְדִי גְזִיר לָא תְקָרְבוּן קֳדָם יְיָ וּבְאַרְעֲכוֹן לָא תַעְבְּדוּן:
@49 וּמִן בַּר עַמְמִין לָא תְקַרְבוּן יָת קֻרְבַּן אֱלָהֲכוֹן מִכָּל אִלֵין אֲרֵי חִבּוּלְהוֹן בְּהוֹן מוּמָא בְהוֹן לָא לְרַעֲוָא יְהוֹן לְכוֹן:
@50 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@51 תּוֹר אוֹ אִמָר אוֹ עִזָא אֲרֵי יִתְיְלִיד וִיהֵי שִׁבְעָא יוֹמִין בָּתַר אִמֵהּ וּמִיוֹמָא תְמִינָאָה וּלְהַלָא יִתִּרְעִי לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ:
@52 וְתוֹרְתָּא אוֹ שֵׂיתָא לֵהּ וְלִבְרֵהּ לָא תִכְּסוּן בְּיוֹמָא חָד:
@53 וַאֲרֵי תִּכְּסוּן נִכְסַת תּוֹדְתָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן תִּכְּסֻנֵהּ:
@54 בְּיוֹמָא הַהוּא יִתְאֲכֵל לָא תַשְׁאֲרוּן מִנֵהּ עַד צַפְרָא אֲנָא יְיָ:
@55 וְתִטְרוּן פִּקוּדַי וְתַעֲבְּדוּן יָתְהוֹן אֲנָא יְיָ:
@56 וְלָא תְחַלְלוּן יָת שְׁמָא דְקוּדְשַׁי וְאִתְקַדַשׁ בְּגוֹ בְּנֵי יִשְׂרָאֵל אֲנָא יְיָ מְקַדִשְּׁכוֹן:
@57 דְאַפִּיק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֶהֱוֵי לְכוֹן לֵאלָהָא אֲנָא יְיָ:
@58 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@59 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן מוֹעֲדַיָא דַיְיָ דִי תְעָרְעוּן יָתְהוֹן מְעָרְעֵי קַדִישׁ אִלֵין אִנוּן מוֹעֲדָי:
@60 שִׁתָּא יוֹמִין תִּתְעֲבֵד עִבִידָא וּבְיוֹמָא שְׁבִיעָאָה שְׁבַת שְׁבָתָא מְעָרַע קַדִישׁ כָּל עִבִידָא לָא תַעֲבְּדוּן שַׁבְּתָא הִיא קֳדָם יְיָ בְּכֹל מוֹתְבָנֵיכוֹן:
@61 אִלֵין מוֹעֲדַיָא דַיְיָ מְעָרְעֵי קַדִישׁ דִי תְעָרְעוּן יָתְהוֹן בְּזִמְנֵיהוֹן:
@62 בְּיַרְחָא קַדְמָאָה בְּאַרְבְּעַת עַשְׂרָא לְיַרְחָא בֵּין שִׁמְשַׁיָא פִּסְחָא קֳדָם יְיָ:
@63 וּבְחַמְשַׁת עַשְׂרָא יוֹמָא לְיַרְחָא הָדֵין חַגָא דְפַטִירַיָא קֳדָם יְיָ שִׁבְעָא יוֹמִין פַּטִיר תֵּיכְלוּן:
@64 בְּיוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פָּלְחַן לָא תַעֲבְּדוּן:
@65 וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ שִׁבְעָא יוֹמִין בְּיוֹמָא שְׁבִיעָאָה מְעָרַע קַדִישׁ כָּל עִבִידַת פָּלְחָן לָא תַעֲבְּדוּן:
@66 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@67 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעֲלוּן לְאַרְעָא דִי אֲנָא יָהֵב לְכוֹן וְתַחְצְדוּן יָת חֲצָדַהּ וְתַיְתוּן יָת עוּמְרָא רֵישׁ חֲצָדְכוֹן לְוָת כַּהֲנָא:
@68 וִירִים יָת עוּמְרָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן מִבָּתַר יוֹמָא טָבָא יְרִימִנֵהּ כַּהֲנָא:
@69 וְתַעֲבְּדוּן בְּיוֹמָא דַאֲרָמוּתְכוֹן יָת עוּמְרָא אִמַר שְׁלִים בַּר שַׁתֵּהּ לַעֲלָתָא קֳדָם יְיָ:
@70 וּמִנְחָתֵהּ תְּרֵין עֶשְׂרוֹנִין סֻלְתָּא דְפִילָא בִמְשַׁח קֻרְבָּנָא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא וְנִסְכֵּהּ חַמְרָא רַבְעוּת הִינָא:
@71 וּלְחֵם וּקְלִי וּפֵרוּכָן לָא תֵיכְלוּן עַד כְּרַן יוֹמָא הָדֵין עַד אַיְתוֹאֵיכוֹן יָת קֻרְבָּן אֱלָהָכוֹן קְיַם עָלָם לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:
@72 וְתִמְנוּן לְכוֹן מִבָּתַר יוֹמָא טָּבָא מִיוֹם אַיְתוֹאֵיכוֹן יָת עוּמְרָא דַאֲרָמוּתָא שִׁבְעָא שָׁבוּעִין שַּׁלְמִין יְהֶוְיָן (נ''א תְּהֶוְיָן):
@73 עַד מִבָּתַר שְׁבוּעֲתָא שְׁבִיעֵתָא תִּמְנוּן חַמְשִׁין יוֹמִין וּתְקַרְבוּן מִנְחָתָא חֲדַתָּא קֳדָם יְיָ:
@74 מִמוֹתְבָנֵיכוֹן תַּיְתוּן לְחֵם אֲרָמוּתָא תַּרְתֵּין (גְרִיצַן) תְּרֵין עֶשְׂרוֹנִין סֻלְתָּא יְהֶוְיָן חֲמִיעַ יִתְאַפְיָן בִּכּוּרִין קֳדָם יְיָ:
@75 וּתְקָרְבוּן עַל לַחְמָא שִׁבְעָא אִמְרִין שַׁלְמִין בְּנֵי שְׁנָא וְתוֹר בַּר תּוֹרֵי חַד וְדִכְרִין תְּרֵין יְהוֹן עֲלָתָא קֳדָם יְיָ וּמִנְחָתְהוֹן וְנִסְכֵּיהוֹן קֻרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@76 וְתַעְבְּדוּן צְפִיר בַּר עִזֵי חַד לְחַטָאתָא וּתְרֵין אִמְרִין בְּנֵי שְׁנָא לְנִכְסַת קוּדְשַׁיָא:
@77 וִירִים כַּהֲנָא יָתְהוֹן עַל לְחֵם בִּכּוּרַיָא אֲרָמוּתָא קֳדָם יְיָ עַל תְּרֵין אִמְרִין קוּדְשָׁא יְהוֹן קֳדָם יְיָ לְכַהֲנָא:
@78 וּתְעָרְעוּן בִּכְרַן יוֹמָא הָדֵין מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פָּלְחָן לָא תַעֲבְּדוּן קְיַם עָלָם בְּכָל מוֹתְבָנֵיכוֹן לְדָרֵיכוֹן:
@79 וּבְמֶחֱצָדְכוֹן יָת חֲצָדָא דְאַרְעֲכוֹן לָא תְשֵׁיצֵי פָּאתָא דְחַקְלָךְ בְּמֶחֱצָדָךְ וּלְקָטָא דַחֲצָדָךְ לָא תְלַקֵט לְעַנְיֵי וּלְגִיוֹרֵי תִּשְׁבּוֹק יָתְהוֹן אֲנָא יְיָ אֱלָהֲכוֹן:
@80 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@81 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר בְּיַרְחָא שְׁבִיעָאָה בְּחַד לְיַרְחָא יְהֵי לְכוֹן נְיָחָא דוּכְרָן יַבָּבָא מְעָרַע קַדִישׁ:
@82 כָּל עִבִידַת פָלְחָנָא לָא תַעֲבְּדוּן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ:
@83 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@84 בְּרַם בְּעַשְׂרָא לְיַרְחָא שְׁבִיעָאָה הָדֵין יוֹמָא דְכִפּוּרַיָא הוּא מְעָרַע קַדִישׁ יְהֵי לְכוֹן וּתְעַנוּן יָת נַפְשָׁתֵיכוֹן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ:
@85 וְכָל עִבִידָא לָא תַעֲבְּדוּן בִּכְרַן יוֹמָא הָדֵין אֲרֵי יוֹמָא דְכִפּוּרַיָא הוּא לְכַפָּרָא עֲלֵיכוֹן קֳדָם יְיָ אֱלָהֲכוֹן:
@86 אֲרֵי כָל אֲנָשָׁא דִי לָא מִתְעַנֵי בִּכְרַן יוֹמָא הָדֵין וְיִשְׁתֵּיצֵי מֵעַמָהָא:
@87 וְכָל אֱנַשׁ דִי תַעְבֵּד כָּל עִבִידָא בִּכְרַן יוֹמָא הָדֵין וְאוֹבֵד יָת אֲנָשָׁא הַהִיא מִגוֹ עַמָהּ:
@88 כָּל עִבִידָא לָא תַעֲבְּדוּן קְיַם עָלָם לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:
@89 שְׁבַת שְׁבָתָא הוּא לְכוֹן וּתְעַנוּן יָת נַפְשָׁתֵיכוֹן בְּתִשְׁעָה לְיַרְחָא בְּרַמְשָׁא מֵרַמְשָׁא עַד רַמְשָׁא תְּנוּחוּן נְיַחֲכוֹן:
@90 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@91 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר בְּחַמְשָׁא עַשְׂרָא יוֹמָא לְיַרְחָא שְׁבִיעָאָה הָדֵין חַגָא דִמְטַלַיָא שִׁבְעַת יוֹמִין קֳדָם יְיָ:
@92 בְּיּוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ כָּל עִבִידַת פָּלְחָן לָא תַעֲבְּדוּן:
@93 שִׁבְעָא יוֹמִין תְּקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ בְּיוֹמָא תְמִינָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ כְּנֵשׁ תְּהוֹן כָּל עִבִידַת פָּלְחַן לָא תַעֲבְּדוּן:
@94 אִלֵין מוֹעֲדַיָא דַיְיָ דִי תְעָרְעוּן יָתְהוֹן מְעָרְעֵי קַדִישׁ לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ עֲלָתָא וּמִנְחָתָא נִכְסַת קוּדְשִׁין וְנִסוּכִין פִּתְגַם יוֹם בְּיוֹמֵהּ:
@95 בַּר שַׁבַּיָא דַיְיָ וּבַר מַתְּנָתֵיכוֹן וּבַר כָּל נִדְרֵיכוֹן וּבַר כָּל נִדְבָתֵיכוֹן דִי תִתְּנוּן קֳדָם יְיָ:
@96 בְּרַם בְּחַמְשָׁא עֲשַׂר יוֹמָא לְיַרְחָא שְׁבִיעָאָה בְּמִכְנְשֵׁיכוֹן יָת עֲלַלַת אַרְעָא תְּחַגוּן יָת חַגָא קֳדָם יְיָ שִׁבְעָא יוֹמִין בְּיוֹמָא קַדְמָאָה נְיָחָא וּבְיוֹמָא תְמִינָאָה נְיָחָא:
@97 וְתִסְבוּן לְכוֹן בְּיוֹמָא קַדְמָאָה פֵּרֵי אִילָנָא אֶתְרוֹגִין וְלֻלָבִין וַהֲדַסִין וְעַרְבִין דִנְחָל וְתֶחֱדוּן קֳדָם יְיָ אֱלָהֲכוֹן שַׁבְעַת יוֹמִין:
@98 וּתְחַגוּן יָתֵהּ חַגָא קֳדָם יְיָ שַׁבְעַת יוֹמִין בְּשַׁתָּא קְיַם עָלָם לְדָרֵיכוֹן בְּיַרְחָא שְׁבִיעָאָה תְּחַגוּן יָתֵהּ:
@99 בִּמְטַלַיָא תֵיתְבוּן שַׁבְעַת יוֹמִין כָּל יַצִיבָא בְּיִשְׂרָאֵל יֵתְבוּן בִּמְטַלַיָא:
@100 בְּדִיל דְיִדְעוּן דָרֵיכוֹן אֲרֵי בִמְטַלָיוּת עֲנָנֵי אוֹתֵבִית יָת בְּנֵי יִשְׂרָאֵל בְּאַפָּקוּתִי יָתְהוֹן מֵאַרְעָא דְמִצְרַיִם אֲנָא יְיָ אֱלָהֲכוֹן:
@101 וּמַלִיל מֹשֶׁה יָת סְדַר מוֹעֲדַיָא דַיְיָ וְאַלֵפִנוּן לִבְנֵי יִשְׂרָאֵל:
@102 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@103 פַּקֵד יָת בְּנֵי יִשְׂרָאֵל וְיִסְבוּן לָךְ מְשַׁח זֵיתָא דַכְיָא כָּתִישָׁא לְאַנְהָרָא לְאַדְלָקָא בוֹצִינַיָא תְּדִירָא:
@104 מִבָּרָא לְפָרֻכְתָּא דְסַהֲדוּתָא בְּמַשְׁכַּן זִמְנָא יַסְדַר יָתֵהּ אַהֲרֹן מֵרַמְשָׁא עַד צַפְרָא קֳדָם יְיָ תְּדִירָא קְיָם עָלָם לְדָרֵיכוֹן:
@105 עַל מְנַרְתָּא דָכִיתָא יַסְדַר יָת בּוֹצִינַיָא קֳדָם יְיָ תְּדִירָא:
@106 וְתִסַב סֻלְתָּא וְתֵיפֵי יָתַהּ תַּרְתָּא עַשְׂרֵי גְרִיצָן תְּרֵין עֶשְׂרוֹנִין תְּהֵי גְרִצְתָּא חֲדָא:
@107 וּתְשַׁוִי יָתְהוֹן תַּרְתֵּי סִדְרִין שִׁית סִדְרָא עַל פָּתוֹרָא דַכְיָא קֳדָם יְיָ:
@108 וְתִתֵּן עַל סִדְרָא לְבֹנְתָּא דָכִיתָא וּתְהֵי לִלְחֵם לְאִדְכַּרְתָּא קֻ:רבָּנָא:קָדָם יְיָ:
@109 בְּיוֹמָא דְשַׁבְּתָא בְּיוֹמָא דְשַׁבְּתָא יַסְדְרִנֵהּ קֳדָם יְיָ תְּדִירָא מִן קֳדָם בְּנֵי יִשְׂרָאֵל קְיַם עָלָם:
@110 וּתְהֵי לְאַהֲרֹן וְלִבְנוֹהִי וְיֵכְלֻנֵהּ בַּאֲתַר קַדִישׁ אֲרֵי קֹדֶשׁ קוּדְשִׁין הוּא לֵהּ מִקֻרְבָּנַיָא דַיְיָ קְיַם עָלָם:
@111 וּנְפַק בַּר אִתְּתָא בַת יִשְׂרָאֵל וְהוּא בַּר גְבַר מִצְרָאָה בְּגוֹ בְּנֵי יִשְׂרָאֵל וּנְצוֹ בְּמַשְׁרִיתָא בַּר אִתְּתָא בַת יִשְׂרָאֵל וְגַבְרָא בַּר יִשְׂרָאֵל:
@112 וּפָרֵשׁ בַּר אִתְּתָא בַת יִשְׂרָאֵל יָת שְׁמָא וְאַרְגֵז וְאַיְתִיאוּ יָתֵהּ לְוָת מֹשֶׁה וְשׁוּם אִמֵהּ שְׁלֹמִית בַּת דִבְרִי לְשִׁבְטָא דְדָן:
@113 וְאַסְרוֹהִי בְּבֵית מַטְרָא עַד דְיִתְפָּרַשׁ לְהוֹן עַל גְזֵרַת מֵימְרָא דַיְיָ:
@114 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@115 אַפֵּק יָת דְאַרְגֵז לְמִבָּרָא לְמַשְּׁרִיתָא וְיִסְמְכוּן כָּל דִי שְׁמָעוּ יָת יְדֵיהוֹן עַל רֵישֵׁהּ וְיִרְגְמוּן יָתֵהּ כָּל כְּנִשְּׁתָּא:
@116 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵל לְמֵימָר גְבַר גְבַר דִי יַרְגֵז קֳדָם אֱלָהֵהּ וִיקַבֵּל חוֹבֵהּ:
@117 וְדִי פָרֵשׁ שְׁמָא דַיְיָ אִתְקְטָּלָא יִתְקְטֵל מִרְגַם יִרְגְמוּן בֵּהּ כָּל כְּנִשְׁתָּא כְּגִיוֹרָא כְּיַצִיבָא בְּפָרָשׁוּתֵהּ שְׁמָא יִתְקְטֵל:
@118 וּגְבַר אֲרֵי יִקְטוֹל כָּל נַפְשָׁא דַאֲנָשָׁא אִתְקְטָלָא יִתְקְטֵל:
@119 וּדְיִקְטוֹל נְפַשׁ בְּעִירָא יְשַׁלְמִנַהּ נַפְשָׁא חֳלַף נַפְשָׁא:
@120 וּגְבַר אֲרֵי יִתֵּן מוּמָא בְּחַבְרֵהּ כְּמָא דִי עֲבַד כֵּן יִתְעֲבֵד לֵיהּ:
@121 תַּבְרָא חֳלַף תַּבְרָא עֵינָא חֳלַף עֵינָא שִׁנָא חֳלַף שִׁנָא כְּמָא דִי יִתֵּן מוּמָא בַּאֲנָשָׁא כֵּן יִתְיְהֵב בֵּהּ:
@122 וּדְיִקְטוֹל בְּעִירָא יְשַׁלְמִנַהּ וּדְיִקְטוֹל אֲנָשָׁא יִתְקְטֵל:
@123 דִינָא חֲדָא יְהֵי לְכוֹן כְּגִיוֹרָא כְּיַצִיבָא יְהֵי אֲרֵי אֲנָא יְיָ אֱלָהֲכוֹן:
@124 וּמַלִיל מֹשֶׁה עִם בְּנֵי יִשְׂרָאֵל וְאַפִּיקוּ יָת דְאַרְגֵז לְמִבָּרָא לְמַשְׁרִיתָא וּרְגָמוּ יָתֵהּ אַבְנָא וּבְנֵי יִשְׂרָאֵל עֲבָדוּ כְּמָא דִי פַּקֵיד יְיָ יָת מֹשֶׁה: פפפ:

@1 **אמר אל הכהנים.** אמר ואמרת, להזהיר גדולים על הקטנים: **בני אהרן.** יכול חללים, תלמוד לומר הכהנים: **בני אהרן.** אף בעלי מומין במשמע: **בני אהרן.** ולא בנות אהרן: **לא יטמא בעמיו.** בעוד שהמת בתוך עמיו, יצא מת מצוה:
@2 **כי אם לשארו.** אין שארו אלא אשתו:
@3 **הקרובה.** לרבות את הארוסה: **אשר לא היתה לאיש.** למשכב: **לה יטמא.** מצוה:
@4 **לא יטמא בעל בעמיו להחלו.** לא יטמא לאשתו פסולה שהוא מחלל בה בעודה עמו. וכן פשוטו של מקרא לא יטמא בעל בשארו בעוד שהוא בתוך עמיו, שיש לה קוברין, שאינה מת מצוה, ובאיזה שאר אמרתי, באותו שהוא להחלו, להתחלל הוא מכהנתו:
@5 **לא יקרחו קרחה.** על מת. והלא אף ישראל הזהרו על כך, אלא לפי שנאמר בישראל (דברים יד א) בין עיניכם, יכול לא יהא חיב על כל הראש, תלמוד לומר בראשם, וילמדו ישראל מהכהנים בגזרה שוה, נאמר כאן קרחה ונאמר להלן בישראל קרחה, מה כאן כל הראש אף להלן כל הראש במשמע, כל מקום שיקרח בראש. ומה להלן על מת, אף כאן על מת: **ופאת זקנם לא יגלחו.** לפי שנאמר בישראל (ויקרא יט כז) ולא תשחית, יכול לקטו במלקט וברהיטני יהא חיב, לכך נאמר לא יגלחו, שאינו חיב אלא על דבר הקרוי גלוח ויש בו השחתה, וזהו תער: **ובבשרם לא ישרטו שרטת.** לפי שנאמר בישראל (ויקרא שם כח) ושרט לנפש לא תתנו, יכול שרט חמש שריטות לא יהא חיב אלא אחת, תלמוד לומר לא ישרטו שרטת, לחייב על כל שריטה ושריטה. שתיבה זו יתרה היא לדרוש, שהיה לו לכתוב לא ישרטו ואני יודע שהיא שרטת:
@6 **קדשים יהיו.** על כרחם יקדישום בית דין בכך:
@7 **זנה.** שנבעלה בעילת ישראל האסור לה, כגון חיבי כרתות או נתין או ממזר: **חללה.** שנלדה מן הפסולים שבכהנה, כגון בת אלמנה מכהן גדול או בת גרושה וחלוצה מכהן הדיוט, וכן שנתחללה מן הכהנה על ידי ביאת אחד מן הפסולים לכהנה:
@8 **וקדשתו.** על כרחו, שאם לא רצה לגרש, הלקהו ויסרהו עד שיגרש: **קדש יהיה לך.** נהוג בו קדשה לפתוח ראשון בכל דבר ולברך ראשון בסעודה:
@9 **כי תחל לזנות.** כשתתחלל על ידי זנות, שהיתה בה זיקת בעל וזנתה או מן האירוסין או מן הנשואין. ורבותינו נחלקו בדבר, והכל מודים שלא דבר הכתוב בפנויה: **את אביה היא מחללת.** חללה ובזתה את כבודו, שאומרים עליו ארור שזו ילד, ארור שזו גדל:
@10 **לא יפרע.** לא יגדל פרע על אבל. ואיזהו גדול פרע, יותר משלשים יום:
@11 **ועל כל נפשת מת** וגו' **.** באהל המת: **נפשת מת.** להביא רביעית דם מן המת שמטמא באהל: **לאביו ולאמו לא יטמא.** לא בא אלא להתיר לו מת מצוה:
@12 **ומן המקדש לא יצא.** אינו הולך אחר המטה. ועוד מכאן למדו רבותינו שכהן גדול מקריב אונן, וכן משמעו, אף אם מתו אביו ואמו אינו צריך לצאת מן המקדש אלא עובד עבודה: **ולא יחלל את מקדש.** שאינו מחלל בכך את העבודה שהתיר לו הכתוב, הא כהן הדיוט שעבד אונן חלל:
@14 **וחללה.** שנלדה מפסולי כהנה:
@15 **ולא יחלל זרעו.** הא אם נשא אחת מן הפסולות, זרעו המנה חלל מדין קדשת כהנה:
@17 **לחם אלהיו.** מאכל אלהיו, כל סעודה קרויה לחם, כמו (דניאל ה א) עבד לחם רב:
@18 **כי כל איש אשר בו מום לא יקרב.** אינו דין שיקרב, כמו (מלאכי א ח) הקריבהו נא לפחתך: **חרם.** שחטמו שקוע בין שתי העינים, שכוחל שתי עיניו כאחת: **או שרוע.** שאחד מאיבריו גדול מחברו, עינו אחת גדולה ועינו אחת קטנה, או שוקו אחת ארכה מחברתה:
@20 **או גבן.** שורצילו''ש בלע''ז [בעל גבות ארוכות] שגביני עיניו שערן ארוך ושוכב: **או דק.** שיש לו בעיניו דוק שקורין טיל''א [קרום] , כמו (ישעיה מ כב) הנוטה כדוק: **או תבלל.** דבר המבלבל את העין, כגון חוט לבן הנמשך מן הלבן ופוסק בסירא, שהוא עוגל המקיף את השחור, שקוראים פרוניל''א [אישון] , והחוט הזה פוסק את העוגל ונכנס בשחור. ותרגום תבלל חליז, לשון חלזון, שהוא דומה לתולעת אותו החוט. וכן כנוהו חכמי ישראל במומי הבכור חלזון נחש עינב (בכורות לח א) : **גרב וילפת.** מיני שחין הם: גרב, זו החרס. שחין היבש מבפנים ומבחוץ: ילפת, היא חזזית המצרית. ולמה נקראת ילפת שמלפפת והולכת עד יום המיתה, והוא לח מבחוץ ויבש מבפנים. ובמקום אחר קורא לגרב שחין, הלח מבחוץ ויבש מבפנים, שנאמר (דברים כח כז) ובגרב ובחרס, כשסמוך גרב אצל חרס קורא לילפת גרב, וכשהוא סמוך אצל ילפת קורא לחרס גרב, כך מפורש בבכורות (מא א) : **מרוח אשך.** לפי התרגום מריס פחדין, שפחדיו מרססים, שביצים שלו כתותין. פחדין כמו (איוב מ יז) גידי פחדו ישורגו:
@21 **כל איש אשר בו מום.** לרבות שאר מומין: **מום בו.** בעוד מומו בו פסול, הא אם עבר מומו כשר: **לחם אלהיו.** כל מאכל קרוי לחם:
@22 **מקדשי הקדשים.** אלו קדשי הקדשים: **ומן הקדשים יאכל.** אלו קדשים קלים. ואם נאמרו קדשי הקדשים למה נאמרו קדשים קלים, אם לא נאמרו הייתי אומר בקדשי הקדשים יאכל בעל מום, שמצינו שהתרו לזר, שאכל משה בשר המלואים, אבל בחזה ושוק של קדשים קלים לא יאכל, שלא מצינו זר חולק בהן, לכך נאמרו קדשים קלים. כך מפורש בזבחים (קא:) :
@23 **אך אל הפרכת.** להזות שבע הזאות שעל הפרכת: **ואל המזבח.** החיצון. ושניהם הצרכו להכתב, ומפורש בתורת כהנים: **ולא יחלל את מקדשי.** שאם עבד, עבודתו מחללת להפסל:
@24 **וידבר משה.** המצוה הזאת: **אל אהרן ואל בניו ואל כל בני ישראל.** להזהיר בית דין על הכהנים:
@26 **וינזרו.** אין נזירה אלא פרישה, וכן הוא אומר (יחזקאל יד ז) וינזר מאחרי, (ישעיה א ד) נזורו אחור, יפרשו מן הקדשים בימי טמאתן. דבר אחר: וינזרו מקדשי בני ישראל אשר הם מקדישים לי ולא יחללו את שם קדשי. סרס המקרא ודרשהו, אשר הם מקדשים לי ולא יחללו את שם קדשי: **אשר הם מקדשים לי.** לרבות קדשי כהנים עצמן:
@27 **כל איש אשר יקרב.** אין קריבה זו אלא אכילה, וכן מצינו שנאמרה אזהרת אכילת קדשים בטמאה בלשון נגיעה בכל קדש לא תגע (ויקרא יב ד) , אזהרה לאוכל. ולמדוה רבותינו מגזרה שוה. ואי אפשר לומר שחיב על הנגיעה, שהרי נאמר כרת על האכילה בצו את אהרן (ויקרא ז כ. כא) שתי כריתות זו אצל זו, ואם על הנגיעה חיב לא הצרך לחיבו על האכילה, וכן נדרש בתורת כהנים וכי יש נוגע חיב, אם כן מה תלמוד לומר יקרב, משיכשר לקרב, שאין חיבין עליו משום טמאה, אלא אם כן קרבו מתיריו. ואם תאמר שלש כריתות בטמאת כהנים למה, כבר נדרשו במסכת שבועות אחת לכלל ואחת לפרט וכו' (שבועות ז א) : **וטמאתו עליו.** וטמאת האדם עליו, יכול בבשר הכתוב מדבר, וטמאתו של בשר עליו, ובטהור שאכל את הטמא הכתוב מדבר, הרי כבר נאמר (ויק' ז יט) והבשר אשר יגע בכל טמא לא יאכל, אלא על כרחך ממשמעו אתה למד, במי שטמאתו פורחת ממנו הכתוב מדבר, וזהו האדם שיש לו טהרה בטבילה: **ונכרתה** וגו' **.** יכול מצד זה לצד זה, יכרת ממקומו ויתישב במקום אחר, תלמוד לומר אני ה', בכל מקום אני:
@28 **מזרע אהרן.** אין לי אלא זרעו, גופו מנין, תלמוד לומר והוא צרוע, שיכול הואיל ומקריב אונן יקריב צרוע וזב, תלמוד לומר והוא: **עד אשר יטהר.** ביאת השמש, או אינו אלא טבילה, נאמר כאן וטהר, ונאמר למטה וטהר (פסוק ז) ובא השמש וטהר, מה להלן ביאת שמש, אף כאן ביאת שמש: **בכל טמא נפש.** במי שנטמא במת:
@29 **בכל שרץ אשר יטמא לו.** בשעור הראוי לטמא, בכעדשה: **או באדם.** במת: **אשר יטמא לו.** כשיעורו לטמא, וזהו כזית: **לכל טמאתו.** לרבות נוגע בזב וזבה, נדה ויולדת ובמצורע:
@30 **נפש אשר תגע בו.** באחד מן הטמאים הללו:
@31 **ואחר יאכל מן הקדשים.** נדרש ביבמות בתרומה, שמתר לאכלה בהערב השמש: **מן הקדשים.** ולא כל הקדשים:
@32 **נבלה וטרפה לא יאכל לטמאה בה.** לענין הטמאה הזהיר כאן, שאם אכל נבלת עוף טהור, שאין לה טמאת מגע ומשא אלא טמאת אכילה בבית הבליעה, אסור לאכול בקדשים. וצריך לומר וטרפה, מי שיש במינו טרפה, יצא נבלת עוף טמא שאין במינו טרפה:
@33 **ושמרו את משמרתי.** מלאכול תרומה בטמאת הגוף: **ומתו בו.** למדנו שהיא מיתה בידי שמים:
@34 **לא יאכל קדש.** בתרומה הכתוב מדבר, שכל הענין דבר בה: **תושב כהן ושכיר.** תושבו של כהן ושכירו, לפיכך תושב זה נקוד פתח, לפי שהוא דבוק. ואיזהו תושב, זה נרצע שהוא קנוי לו עד היובל, ואיזהו שכיר, זה קנוי קנין שנים, שיוצא בשש, בא הכתוב ולמדך כאן שאין גופו קנוי לאדוניו לאכול בתרומתו:
@35 **וכהן כי יקנה נפש.** עבד כנעני שקנוי לגופו: **ויליד ביתו.** אלו בני השפחות. ואשת כהן אוכלת בתרומה מן המקרא הזה, שאף היא קנין כספו. ועוד למד ממקרא אחר (במדבר יח יא) כל טהור בביתך וגו' בספרי:
@36 **לאיש זר.** ללוי ולישראל:
@37 **אלמנה וגרושה.** מן האיש הזר: **וזרע אין לה.** ממנו: **ושבה.** הא אם יש לה זרע ממנו אסורה בתרומה כל זמן שהזרע קים: **וכל זר לא יאכל בו.** לא בא אלא להוציא את האונן שמתר בתרומה. זרות אמרתי לך, ולא אנינות:
@38 **כי יאכל קדש.** תרומה: **ונתן לכהן את הקדש.** דבר הראוי להיות קדש, שאינו פורע לו מעות אלא פירות של חלין, והן נעשין תרומה:
@39 **ולא יחללו** וגו' **.** להאכילם לזרים:
@40 **והשיאו אותם.** את עצמם יטענו עון באכלם את קדשיהם, שהבדלו לשם תרומה וקדשו ונאסרו עליהם. ואנקלוס שתרגם במיכלהון בסואבא, שלא לצורך תרגמו כן: **והשיאו אותם.** זה אחד משלשה אתים שהיה רבי ישמעאל דורש בתורה שמדברים באדם עצמו, וכן (במ' ו יג) ביום מלאת ימי נזרו יביא אתו, הוא יביא את עצמו. וכן (דברים לד ו) ויקבור אתו בגיא, הוא קבר את עצמו, כך נדרש בספרי:
@42 **נדריהם.** הרי עלי: **נדבתם.** הרי זו:
@43 **לרצנכם.** הביאו דבר הראוי לרצות אתכם לפני, שיהא לכם לרצון אפיימני''ט בלע''ז . ואיזהו הראוי לרצון, **תמים זכר בבקר בכשבים ובעזים.** אבל בעולת העוף אין צריך תמות וזכרות, ואינו נפסל במום אלא בחסרון אבר:
@45 **לפלא נדר.** להפריש בדבורו:
@46 **עורת.** שם דבר של מום עורון בלשון נקבה, שלא יהא בו מום של עורת: **או שבור.** לא יהיה: **חרוץ.** ריס של עין שנסדק או שנפגם, וכן שפתו שנסדקה או נפגמה: **יבלת.** ורוא''ה בלע''ז : **גרב.** מין חזזית וכן ילפת. ולשון ילפת, כמו (שופטים טז כט) וילפת שמשון, שאחוזה בו עד יום מיתה, שאין לה רפואה: **לא תקריבו.** שלש פעמים, להזהיר על הקדשן ועל שחיטתן ועל זריקת דמן: **ואשה לא תתנו.** אזהרת הקטרתן:
@47 **שרוע.** אבר גדול מחברו: **וקלוט.** פרסותיו קלוטות: **נדבה תעשה אתו.** לבדק הבית: **ולנדר.** למזבח: **לא ירצה.** איזהו הקדש בא לרצות, הוי אומר זה הקדש המזבח:
@48 **ומעוך וכתות ונתוק וכרות.** בביצים או בגיד: **מעוך.** ביציו מעוכין ביד: **כתות.** כתושים יותר ממעוך: **נתוק.** תלושין ביד עד שנפסקו חוטים שתלויים בהן, אבל נתונים הם בתוך הכיס, והכיס לא נתלש: **וכרות.** כרותין בכלי ועודן בכיס: **ומעוך.** תרגומו ודמריס, זה לשונו בארמית, לשון כתישה: **וכתות.** תרגומו ודרסיס, כמו (עמוס ו יא) הבית הגדול רסיסים, בקיעות דקות, וכן (שבת פ ב) קנה המרסס: **ובארצכם לא תעשו.** דבר זה, לסרס שום בהמה וחיה ואפלו טמאה, לכך נאמר בארצכם, לרבות כל אשר בארצכם, שאי אפשר לומר לא נצטוו על הסרוס אלא בארץ, שהרי סרוס חובת הגוף הוא, וכל חובת הגוף נוהגת בין בארץ בין בחוצה לארץ:
@49 **ומיד בן נכר.** נכרי שהביא קרבן ביד כהן להקריבו לשמים לא תקריבו לו בעל מום. ואף על פי שלא נאסרו בעלי מומין לקרבן בני נח אלא אם כן מחסרי אבר, זאת נוהגת בבמה שבשדות, אבל על המזבח שבמשכן לא תקריבוה, אבל תמימה תקבלו מהם, לכך נאמר למעלה איש איש (לעיל פסוק יח) , לרבות את הנכרים שנודרים נדרים ונדבות כישראל: **משחתם.** חבולהון: **לא ירצו לכם.** לכפר עליכם:
@51 **כי יולד.** פרט ליוצא דופן:
@52 **אתו ואת בנו.** נוהג בנקבה, שאסור לשחוט האם והבן או הבת, ואינו נוהג בזכרים, ומתר לשחוט האב והבן או האב והבת: **אתו ואת בנו.** אף בנו ואותו במשמע:
@53 **לרצנכם תזבחו.** תחלת זביחתכם הזהרו שתהא לרצון לכם. ומהו הרצון, ביום ההוא יאכל. לא בא להזהיר אלא שתהא שחיטה על מנת כן, אל תשחטוהו על מנת לאכלו למחר, שאם תחשבו בו מחשבת פסול לא יהא לכם לרצון. דבר אחר לרצונכם, לדעתכם, מכאן למתעסק שפסול בשחיטת קדשים. ואף על פי שפרט בנאכלים לשני ימים, חזר ופרט בנאכלין ליום אחד שתהא זביחתן על מנת לאכלן בזמנן:
@54 **ביום ההוא יאכל.** לא בא להזהיר אלא שתהא שחיטה על מנת כן, שאם לקבוע לו זמן אכילה, כבר כתוב (ויקרא ז טו) ובשר זבח תודת שלמיו וגו' : **אני ה'.** דע מי גזר על הדבר ואל יקל בעיניך:
@55 **ושמרתם.** זו המשנה: **ועשיתם.** זה המעשה:
@56 **ולא תחללו.** לעבור על דברי מזידין. ממשמע שנאמר ולא תחללו, מה תלמוד לומר ונקדשתי, מסור עצמך וקדש שמי. יכול ביחיד, תלמוד לומר בתוך בני ישראל, וכשהוא מוסר עצמו, ימסור עצמו על מנת למות, שכל המוסר עצמו על מנת הנס, אין עושין לו נס, שכן מצינו בחנניה מישאל ועזריה שלא מסרו עצמן על מנת הנס, שנאמר (דניאל ג יח) והן לא, ידיע להוא לך מלכא די לאלהך לא איתנא פלחין וגו' , מציל ולא מציל, ידיע להוא לך וגו' :
@57 **המוציא אתכם.** על מנת כן: **אני ה'.** נאמן לשלם שכר:
@59 **דבר אל בני ישראל** וגו' **מועדי ה'.** עשה מועדות שיהיו ישראל מלמדין בהם, שמעברים את השנה על גליות שנעקרו ממקומם לעלות לרגל ועדין לא הגיעו לירושלים:
@60 **ששת ימים.** מה ענין שבת אצל מועדות, ללמדך שכל המחלל את המועדות מעלין עליו כאלו חלל את השבתות. וכל המקים את המועדות, מעלין עליו כאלו קים את השבתות:
@61 **אלה מועדי ה'.** למעלה מדבר בעבור שנה, וכאן מדבר בקדוש החדש:
@62 **בין הערבים.** משש שעות ולמעלה: **פסח לה'.** הקרבת קרבן ששמו פסח:
@65 **והקרבתם אשה** וגו' **.** הם המוספין האמורים בפרשת פנחס ולמה נאמרו כאן, לומר לך שאין המוספין מעכבין זה את זה: **והקרבתם אשה לה'.** מכל מקום, אם אין פרים הבא אילים, ואם אין פרים ואילים, הבא כבשים: **שבעת ימים.** כל מקום שנאמר שבעת שם דבר הוא, שבוע של ימים, שטיינ''א בלע''ז [קבוצה של שבעה ימים רצופים] , וכן כל לשון שמונת, ששת, חמשת, שלשת: **מלאכת עבדה.** אפלו מלאכות החשובות לכם עבודה וצורך, שיש חסרון כיס בבטלה שלהן, כגון דבר האבד. כך הבנתי מתורת כהנים, דקתני יכול אף חלו של מועד יהא אסור במלאכת עבודה וכו' :
@67 **ראשית קצירכם.** שתהא ראשונה לקציר: **עמר.** עשירית האיפה, כך היתה שמה, כמו (שמות טז יח) וימדו בעמר:
@68 **והניף.** כל תנופה מוליך ומביא, מעלה ומוריד. מוליך ומביא לעצור רוחות רעות, מעלה ומוריד לעצור טללים רעים: **לרצנכם.** אם תקריבו כמשפט זה, יהיו לרצון לכם: **ממחרת השבת.** ממחרת יום טוב הראשון של פסח, שאם אתה אומר שבת בראשית, אי אתה יודע איזהו:
@69 **ועשיתם:. כבש.** חובה לעמר הוא בא:
@70 **ומנחתו.** מנחת נסכיו: **שני עשרנים.** כפולה היתה: **ונסכה יין רביעית ההין.** אף על פי שמנחתו כפולה, אין נסכיו כפולים:
@71 **וקלי.** קמח עשוי מכרמל רך שמיבשין אותו בתנור: **וכרמל.** הן קליות שקורין גרניד''ש [שבלים] : **בכל משבתיכם.** נחלקו בו חכמי ישראל, יש שלמדו מכאן שהחדש נוהג בחוצה לארץ, ויש אומרים לא בא אלא ללמד שלא נצטוו על החדש אלא לאחר ירשה וישיבה, משכבשו וחלקו:
@72 **ממחרת השבת.** ממחרת יום טוב: **תמימת תהיינה.** מלמד שמתחיל ומונה מבערב, שאם לא כן אינן תמימות:
@73 **השבת השביעת.** כתרגומו שבועתא שביעתא: **עד ממחרת השבת השביעת תספרו.** ולא עד בכלל, והן ארבעים ותשעה יום: **חמשים יום והקרבתם מנחה חדשה לה'.** ביום החמשים תקריבוה. ואומר אני זהו מדרשו, אבל פשוטו עד ממחרת השבת השביעית, שהוא יום חמשים, תספרו. ומקרא מסורס הוא: **מנחה חדשה.** היא המנחה הראשונה שהובאה מן החדש. ואם תאמר, הרי קרבה מנחת העומר, אינה כשאר כל המנחות, שהיא באה מן השעורים:
@74 **ממושבתיכם.** ולא מחוצה לארץ: **לחם תנופה.** לחם תרומה המורם לשם גבוה, וזו היא המנחה החדשה האמורה למעלה: **בכורים.** ראשונה לכל המנחות, אף למנחת קנאות הבאה מן השעורים, לא תקרב מן החדש קודם לשתי הלחם:
@75 **על הלחם.** בגלל הלחם, חובה ללחם: **ומנחתם ונסכיהם.** כמשפט מנחה ונסכים המפורשים בכל בהמה בפרשת נסכים (במדבר טו ד. י) שלשה עשרונים לפר ושני עשרונים לאיל ועשרון לכבש, זו היא המנחה. והנסכים חצי ההין לפר ושלישית ההין לאיל ורביעית ההין לכבש:
@76 **ועשיתם שעיר עזים.** יכול שבעת הכבשים והשעיר האמורים כאן הם שבעת הכבשים והשעיר האמורים בחומש הפקודים, כשאתה מגיע אצל פרים ואילים אינן הם, אמור מעתה אלו לעצמן ואלו לעצמן, אלו קרבו בגלל הלחם ואלו למוספין:
@77 **והניף הכהן אתם תנופה.** מלמד שטעונין תנופה מחיים, יכול כלם, תלמוד לומר על שני כבשים: **קדש יהיו.** לפי ששלמי יחיד קדשים קלים, הזקק לומר בשלמי צבור שהם קדשי קדשים:
@79 **ובקצרכם.** חזר ושנה לעבור עליהם בשני לאוין. אמר רבי אבדימי ברבי יוסף מה ראה הכתוב לתנה באמצע הרגלים, פסח ועצרת מכאן וראש השנה ויום הכפורים והחג מכאן, ללמדך שכל הנותן לקט שכחה ופאה לעני כראוי, מעלין עליו כאלו בנה בית המקדש והקריב קרבנותיו בתוכו: **תעזב.** הנח לפניהם והם ילקטו, ואין לך לסיע לאחד מהם: **אני ה' אלהיכם.** נאמן לשלם שכר:
@81 **זכרון תרועה.** זכרון פסוקי זכרונות ופסוקי שופרות, לזכור לכם עקידת יצחק שקרב תחתיו איל:
@82 **והקרבתם אשה.** המוספים האמורים בחומש הפקודים:
@84 **אך.** כל אכין ורקין שבתורה מיעוטין, מכפר הוא לשבים ואינו מכפר על שאינם שבים:
@87 **והאבדתי.** לפי שהוא אומר כרת בכל מקום ואיני יודע מה הוא, כשהוא אומר והאבדתי, למד על הכרת שאינו אלא אבדן:
@88 **כל מלאכה** וגו' **.** לעבור עליו בלאוין הרבה, או להזהיר על מלאכת לילה כמלאכת יום:
@92 **מקרא קדש.** קדשהו בכסות נקיה ובתפלה, ובשאר ימים טובים במאכל ובמשתה ובכסות נקיה ובתפלה:
@93 **עצרת הוא.** עצרתי אתכם אצלי כמלך שזמן את בניו לסעודה לכך וכך ימים, כיון שהגיע זמנן להפטר אמר בני בבקשה מכם, עכבו עמי עוד יום אחד, קשה עלי פרידתכם: **כל מלאכת עבדה.** אפלו מלאכה שהיא עבודה לכם, שאם לא תעשוה יש חסרון כיס בדבר: **לא תעשו.** יכול אף חלו של מועד יהא אסור במלאכת עבודה, תלמוד לומר היא:
@94 **עלה ומנחה.** מנחת נסכים הקרבה עם העולה: **דבר יום ביומו.** חק הקצוב בחומש הפקודים: **דבר יום ביומו.** הא אם עבר יומו בטל קרבנו:
@96 **אך בחמשה עשר יום:. תחגו.** קרבן שלמים לחגיגה. יכול תדחה את השבת, תלמוד לומר אך, הואיל ויש לה תשלומין כל שבעה: **באספכם את תבואת הארץ.** שיהא חדש שביעי זה בא בזמן אסיפה, מכאן שנצטוו לעבר את השנים, שאם אין העבור, פעמים שהוא בא באמצע הקיץ או החורף: **תחגו.** שלמי חגיגה: **שבעת ימים.** אם לא הביא בזה יביא בזה. יכול יהא מביאן כל שבעה, תלמוד לומר וחגתם אתו, יום אחד במשמע, ולא יותר. ולמה נאמר שבעה, לתשלומין:
@97 **פרי עץ הדר.** עץ שטעם עצו ופריו שוה: **הדר.** הדר באילנו משנה לשנה, וזהו אתרוג: **כפת תמרים.** חסר וי''ו, למד שאינה אלא אחת: **וענף עץ עבת.** שענפיו קלועים כעבותות וכחבלים, וזהו הדס העשוי כמין קליעה:
@99 **האזרח.** זה אזרח: **בישראל.** לרבות את הגרים:
@100 **כי בסכות הושבתי.** ענני כבוד:
@103 **צו את בני ישראל.** זו פרשת מצות הנרות. ופרשת ואתה תצוה לא נאמרה אלא על סדר מלאכת המשכן לפרש צורך המנורה. וכן משמע, ואתה סופך לצוות את בני ישראל על כך: **שמן זית זך.** שלשה שמנים יוצאים מן הזית, הראשון קרוי זך, והן מפורשים במנחות (פט א) ובתורת כהנים: **תמיד.** מלילה ללילה, כמו עולת תמיד שאינה אלא מיום ליום:
@104 **לפרכת העדת.** שלפני הארון, שהוא קרוי עדות. ורבותינו דרשו על נר מערבי, שהוא עדות לכל באי עולם שהשכינה שורה בישראל, שנותן בה שמן כמדת חברותיה וממנה היה מתחיל ובה היה מסים: **יערך אתו אהרן מערב עד בקר.** יערוך אותו עריכה הראויה למדת כל הלילה, ושערו חכמים חצי לוג לכל נר ונר, והן כדאי אף ללילי תקופת טבת, ומדה זו הקבעה להם:
@105 **המנרה הטהרה.** שהיא זהב טהור. דבר אחר על טהרה של מנורה, שמטהרה ומדשנה תחלה מן האפר:
@107 **שש המערכת.** שש חלות המערכה האחת: **השלחן הטהר.** של זהב טהור. דבר אחר על טהרו של שלחן, שלא יהיו הסניפין מגביהין את הלחם מעל גבי השלחן:
@108 **ונתת על המערכת.** על כל אחת משתי המערכות היו שני בזכי לבונה, מלא קומץ לכל אחת: **והיתה.** הלבונה הזאת: **ללחם לאזכרה.** שאין מן הלחם לגבוה כלום, אלא הלבונה נקטרת כשמסלקין אותו בכל שבת ושבת. והיא לזכרון ללחם, שעל ידה הוא נזכר למעלה, כקומץ שהוא אזכרה למנחה:
@110 **והיתה.** המנחה הזאת, שכל דבר הבא מן התבואה בכלל מנחה הוא: **ואכלהו.** מוסב על הלחם, שהוא לשון זכר:
@111 **ויצא בן אשה ישראלית.** מהיכן יצא, רבי לוי אומר מעולמו יצא. רבי ברכיה אומר מפרשה שלמעלה יצא. לגלג ואמר ביום השבת יערכנו, דרך המלך לאכול פת חמה בכל יום, או שמא פת צוננת של תשעה ימים, בתמיהה. ומתניתא אמרה מבית דינו של משה יצא מחיב. בא לטע אהלו בתוך מחנה דן, אמרו לו מה טיבך לכאן, אמר להם מבני דן אני. אמרו לו (במדבר ב) איש על דגלו באתת לבית אבותם כתיב. נכנס לבית דינו של משה ויצא מחיב, עמד וגדף: **בן איש מצרי.** הוא המצרי שהרגו משה: **בתוך בני ישראל.** מלמד שנתגיר: **וינצו במחנה.** על עסקי המחנה: **ואיש הישראלי.** זה שכנגדו, שמחה בו מטע אהלו:
@112 **ויקב.** כתרגומו ופרש, שנקב שם המיוחד וגדף, והוא שם המפורש ששמע מסיני: **ושם אמו שלמית בת דברי.** שבחן של ישראל שפרסמה הכתוב לזו, לומר, שהיא לבדה היתה זונה: **שלמית.** דהות פטפטה שלם עלך, שלם עלך, שלם עליכון, מפטפטת בדברים שואלת בשלום הכל: **בת דברי.** דברנית היתה מדברת עם כל אדם, לפיכך קלקלה: **למטה דן.** מגיד שהרשע גורם גנאי לו גנאי לאביו גנאי לשבטו, כיוצא בו (שמות לא ו) אהליאב בן אחיסמך למטה דן, שבח לו שבח לאביו שבח לשבטו:
@113 **ויניחהו.** לבדו, ולא הניחו מקושש עמו, ששניהם היו בפרק אחד. ויודעים היו שהמקושש במיתה, שנאמר (שמות לא יד) מחלליה מות יומת אבל לא פרש להם באיזו מיתה, לכך נאמר (במדבר טו לד) כי לא פרש מה יעשה לו. אבל במקלל הוא אומר לפרוש להם, שלא היו יודעים אם חיב מיתה אם לאו:
@115 **השמעים.** אלו העדים: **כל.** להביא את הדינים: **את ידיהם.** אומרים לו דמך בראשך ואין אנו נענשים במיתתך שאתה גרמת לך: **כל העדה.** במעמד כל העדה. מכאן ששלוחו שלאדם כמותו:
@116 **ונשא חטאו.** בכרת, כשאין התראה:
@117 **ונקב שם.** אינו חיב עד שיפרש את השם, ולא המקלל בכנוי: **ונקב.** לשון קללה, כמו (במדבר כג ח) מה אקב:
@118 **ואיש כי יכה.** לפי שנאמר (שמות כא יב) מכה איש ומת, אין לי אלא שהרג את האיש, אשה וקטן מנין, תלמוד לומר כל נפש אדם:
@121 **כן ינתן בו.** פרשו רבותינו, שאינו נתינת מום ממש אלא תשלומי ממון, שמין אותו כעבד, לכך כתוב בו לשון נתינה, דבר הנתון מיד ליד:
@122 **ומכה בהמה ישלמנה.** למעלה דבר בהורג בהמה, וכאן דבר בעושה בה חבורה: **ומכה אדם יומת.** אפלו לא הרגו אלא עשה בו חבורה, שלא נאמר כאן נפש ובמכה אביו ואמו דבר הכתוב, ובא להקישו למכה בהמה מה מכה בהמה מחיים, אף מכה אביו ואמו מחיים, פרט למכה לאחר מיתה, לפי שמצינו שהמקללו לאחר מיתה חיב, הצרך לומר במכה שפטור. ומה בבהמה בחבלה, שאם אין חבלה אין תשלומין, אף מכה אביו ואמו אינו חיב עד שיעשה בהם חבורה:
@123 **אני ה' אלהיכם.** אלהי כלכם, כשם שאני מיחד שמי עליכם כך אני מיחד שמי על הגרים:
@124 **ובני ישראל עשו.** כל המצוה האמורה בסקילה במקום אחר דחיה, רגימה ותליה:
@125 **והכהנים הלוים.** משבט לוי: **בני צדוק.** לפי שהיה כ"ג ששימש ראשון במקדש בימי שלמה נקראו על שמו: **בתעות.** קנאינשר"ר בלע"ז:
@127 **אל שערי החצר הפנימית.** לפני ולפנים בי"ה: **ולא יעלה עליהם צמר.** תכלת שהיה במעיל ובאבנט לא ילבשנו בי"ה בעבודת פנים: **וביתה.** ולפנים:
@128 **פארי.** קאפייל"ש בלע"ז: **לא יחגרו ביזע.** שנינו בברייתא אין חוגרין במקום שמזיעין לא למעלה מאציליהם ולא למטה ממתניהם שהוא מקום זיעה אנלאשויי"רא בלע"ז ל"א אסרה התורה לכהנים מלבושי הצמר כי הצמר מזיע הגוף ומזיע את הבשר, ( סא"א ):
@129 **אל החצר החיצונה.** לפי שהיה מדבר בהיכל לפני ולפנים וקראם חצר הפנימית ואצלם יש לו לקרות עזרת ישראל חצר החיצונה לכך הוצרך לכפול שתי פעמים לומר שעל עזרת נשים הוא אומר מקום שכל ישראל נכנסין: **והניחו אותם בלשכות הקודש.** כמו שאמר מרע"ה ( ויקרא ט"ז ) ופשט את בגדי הבד אשר לבש והניחם שם: **ולא יקדשו את העם.** ת"י ולא יתערבון עם עמא בלבושיהון כלומר לא יגעו אל העם בבגדיהם הקדושים שאין בגדי חול טהורין אצל בגדי הקודש:
@130 **וראשם לא יגלחו.** להעביר את כל השער: **ופרע לא ישלחו.** גידול שער לא ירבו: **כסום יכסמו.** ככוסמת הזו שסדורין בשבולת ראשו של זה לצד עיקרו של זה כך שמעתי משמו של רבי מנחם זצ"ל ויתכן לפרשו לשון מדת דבר השוה לא גזיזת ראש ולא גדול שער אלא במדה שוה אמולי"ר בלע"ז:
@131 **בבואם אל החצר הפנימית.** אל ההיכל:
@132 **כי אם בתולות.** יקחו. הכהנים הגדולים אבל יש מן הכהנים אשר יקחו את האלמנה כגון הדיוטין וזהו מכהן יקחו יש מן הכהן שמותרין באלמנה, מצאתי: **אשר תהיה אלמנה.** גמורה פרט לגרושה וחלוצה אע"פ שפנויה היא אסורה אף להדיוט:
@136 **ואחרי טהרתו.** אחר פרישתו מן המת כך שנויה במ"ק:
@137 **וביום בואו.** תחילה אל הקדש להתחנך לעבודה יקריב חטאתו זו עשירית האיפה שלו כך שנויה במ"ק שהכהן הדיוט טעון עשירית האיפה ביום חינוכו כענין שנאמר ( שם ו' ) זה קרבן אהרן ובניו וגו' וכמו שמפרש במסכת מנחות:
@138 **והיתה להם.** הכהונה לנחלה:
@139 **חרם.** לשון קדש וכן כל לשון חרמה שהוא על הקדש:
@140 **להניח.** אפושי"ר בלע"ז כמו ( שמות ח' ) וינח בכל גבול מצרים:
@141 **כל נבלה וטרפה וגו'.** לפי שהותרה להם מליקת חטאת העוף שהיא נבלה וטריפה הוצרך להזהירם על שאר נבלות וטריפות כך פירשו רבותינו:

@1 **אמור אל הכהנים בני אהרן.** מגיד שאין אלו האזהרות נוהגות כי אם בזכרי הכהונות להיותם נבדלים לעבוד השם יתע' וזה נוהג בכהנים לא בחללים כי הם מחוללין מהכהנה:
@1 **לנפש לא יטמא בעמיו.** מגיד שאין טמאת מת נוהגת בגוים כי לרחקם משלמות אנושי כמעט שלא נפקד מהם דבר בסבת המות יהיה בו תועלת לאדם במה שהוא אדם והזהיר הכהנים מלהטמא במתים כאלו יאמר שהם ראוים שיתעבו הענינים החמריים אם לא מצד מה שבהם תועלת לצורה האנושית ולזה יהיו מתרחקים מלהטמא למת ואפשר שיהיה הרצון באמרו בעמיו שיהיה המת בעמיו רוצה לומר שיהיו לו קרובים אבל מטמא הוא למת שאינו בעמיו והוא שאין לו קוברין וכן פירשו בתורת כהנים וכבר יתבאר שזה העניין מצוה ממה שאמר' תורה בענין הנתלים לא תלין נבלתו על העץ כי קבור תקברנו ביום ההוא והנה אם צותה אותנו התורה לקבור כמו או הרשעים כ"ש שמצוה בזה בשאר המתים:
@2 **כי אם לשארו הקרוב אליו.** רצה השם יתעלה שיתטמאו לשאר בשר כדי שיתאבלו עליהם באופן ראוי כי בזה תועלת כמו שביארנו בענין ספוד אברהם לשרה ובכותו עליה ולזה באה המצוה לכהנים שיתטמאו לקרוביהם כמו שיתבאר והנה זכר מאלו הקרובים אביו ואמו ובנו ובתו ואחיו ואחותו והתנה באחותו שתהיה בתולה שאם נבעלה באי זה אופן שיהיה אינו מטמא לה והנה התנה שתהיה קרובה אליו והיא אחותו מאביו לא אחותו מאמו כי אינה יורש' ולזה התנה במוחלט כי אם לשארו הקרוב אליו ומה יתבאר שאינו מטמא לאחיו מאמו ובכלל הנה כמו שבנו ובתו הם ראוים לירשו כן ראוי שיהיה בטמא לאחיו ולאחותו הראוין לירשו ומזה יתבאר מאמרו הקרובה אליו שאינו מטמא לאחיו מאמו ובכלל הנה כמו שבנו ובתו הם ראוים לירשו כן ראוי שיהיה נטמא לאחיו ולאחותו הראוין לירשו ומזה יתבאר מאמרו הקרובה אליו שאינו מטמא לאחותו הארוסה כי אינה קרובה אליו אבל היא קרובה לאישה להדבק בה ולהפרד מאחיה:
@3 **אשר לא היתה לאיש.** למדתנו התורה שאינו מטמא לאחותו שהיתה נשואה אע"פ שנתגרשה כי כבר היתה לאיש:
@3 **לה יטמא.** מגיד שהוא חיי' להטמא לה וכן ההקש בשאר הקרובים הנזכרים כי הם ראויים בזה הדין כמוה וראוי שנדע שהוא אינו מטמא להם אלא בזמן שהם שלמי' שנאמר לאביו ולאמו וגו'. לה יטמא שמורה שהן שלמים והוא מבוא' מצד הוראת הגדר שלא יקראהו הנפלי' בנו ובתו כי לא נשלמ' הוייתם ולזה לא יטמא להם וכך הוא מבוא' שלא הותר לכהנים להטמא אלא לאלו לא לזולתם עמם:
@4 **לא יטמא בעל בעמיו להחלו.** ראוי שתדע שכבר יאמר בעמיו על אשתו כמו שאמר בזאת הפרש' ולא יחלל זרעו בעמיו ומאמרו בעל הנה יתבאר שהתורה צותה אותו שלא יטמא מצד מה שהוא בעל והוא מבואר שהוא בעל מצד אשתו ולזה יהיה הרצון בה שלא יטמא הבעל באשתו שהוא להחלו והוא אשתו הפסולה ואע"פ שאיננה מחללת בעלה אבל היא חללה ובניה חללים הנה אמר שהיא לחללו באופן שאמר בבת כהן את אביה היא מחללת וזה כי אע"פ שהנושא הפסולה לו אינו חלל הנה זה הענין חלול מה לו כי הוא מוריד זרעו מקדושתו ומזה המקום יתבאר שאין כהן מיטמא לאשתו הפסולה וראוי שיתבאר מזה שאפשר לו להטמא לאשתו הכשרה אבל לא יתבאר מזה שיחוייב להטמא לאשתו הכשרה:
@5 **לא יקרחו קרחה בראשם.** ר"ל על מת שמת להם כבר ביאר זה במקום אחר ואמר לא תשימו קרחה בין עיניכם למת ומגיד שהוא חייב על כל קרחה וקרחה באי זה מקום שיהיה מהראש שנאמר בראשם והנה שיעור הקרחה יתבאר ממה שאמר בשעורי הנגעים שהוא כגריס הקלקי:
@5 **ופאת זקנם לא יגלחו.** כבר התבאר פירושו בפר' הקודמת:
@5 **ובבשרם לא ישרטו שרטת.** ר"ל על מת כמו שהתב' בפרש' הקודמת אמר ושרט לנפש לא תתנו בבשרכם:
@6 **קדושי' יהיו לאלהיהם.** ר"ל שינהגו קדושה יתרה בעצמם להתרחק מעניינים המגונים:
@6 **ולא יחללו שם אלהיה'.** ר"ל שאם לא נהגו עצמם בקדושה הנה הם משפילים על אנשים מדרגת השם יתע' אשר הם מוכנים לשרתו:
@7 **אשה זונה וחללה לא יקחו.** ראוי שתדע כי הזונה לפי הוראת הגדר היא הנבעלת לאיש האסור לנשאה והרצון בזה שהיא נוטה מהאדם המותר לה אל אדם האסור לה וחללה היא לפי שהוראת הגדר שנבעלה לכהן הפסול לה כי הכהן מחלל אותה כמו שאמר אחר זה ולא יחלל זרעו בעמיו או שבא מפסולי כהנה כי הזרע ההוא הוא מתחלל וחגם כן הנה כמו שהזונה היא זונה מצד הבעילה כן ראוי שתהיה האשה חללה מצד הבעילה והוא מבואר שלא עבר על לאו זה אם לא נשאה שנ' לא יקחו:
@7 **ואשה גרושה מאישה לא יקחו.** כבר יורה היותה גרושה שנמצא בה דבר גנות ואין ראוי שיקח הכהן לאשה מי שלא הית' ראויה לאשה:
@7 **כי קדוש הוא לאלהיו.** ולזה אין ראוי שיקח אלו הנשים אשר הם בזה האופן מהגנות:
@8 **וקדשתו כי את לחם אלהיך הוא מקריב.** ר"ל כבר תצוה לקדשו ולתת לו מהכבוד חקו מפני כבוד השם יתעלה כי כל מה שיהיו הכהנים יותר מכובדים בעיני האנשים תגדל מעלת מי שהם מיוחדים לשרתו בעיניהם ולזה צוה השם יתעלה שיהיה להם בגדי קדש לכבוד לתפארת וצוה בקרבנות שיהיו תמימים:
@9 **ובת איש כהן כי תחל לזנות.** לפי שאמרה התורה באש תשרף ולא אמרה מות תמות באש תשרף כמו שאמרה בשאר העונשים מות יומת עם הארץ ירגמוהו באבן. מות יומת אביו ואמו קלל דמיו בו. מות יומתו דמיהם בם. מות יומתו באבן ירגמו אותם דמיהם בם. למדנו שכבר התבאר שהיא במיתה ולזה לא נצטרכה התורה לזכור שהיא במתיה רק לזכור באי זו מיתה תמות ולזה הוא מבואר שהזנות הזה היא ענשו בישראל מיתה אלא שהיא יותר קלה כי מפני היותה מחללת אביה החמירה התורה במיתתה ולזה יתבאר שהנשואה היתה מיתתה בחנק אם לא היתה בת כהן כמו שהתבאר בפרש' הקודמת והנה היא מחללת את אביה שיבזוהו אנשים מפני שיצא ממנו זרע פגום בזה האופן:
@10 **והכהן הגדול מאחיו וגו'.** ר"ל שכיון שנמשח בשמן המשחה ולבש בגדי כהן גדול אע"פ שלא לבשם כי אם פעם א' הנה תהיינה נוהגו' בו אלו המצות היתרות:
@10 **את ראשו לא יפרע ובגדיו לא יפרום.** לפי שהוא תמיד במקדש הזהירה אותו התורה שלא יהיה מגודל שער וקרוע בגדים בעת מהעתי' וכבר יתבאר שהוא היה תמיד במקדש מהציץ שהזהירה בו שיהיה על מצחו תמיד:
@11 **ועל כל נפשות מת לא יבא.** לפי שזכר אחר הכלל הזה אביו ואמו למדנו שההבדל בין כהן גדול לכהן הדיוט אינו אלא בכמו אלו הקרובים לא במת מצוה והוא המת שאינו בעמיו:
@12 **ומן המקדש לא יצא ולא יחלל את מקדש אלהיו וגו'.** למדנו שזאת האזהרה היא גם כן בכהן הדיוט בפרש' שמיני ובהיות הענין כן הנה ראוי שנעין מה ההבדל בזה בין כהן גדול לכהן הדיוט אשר בעבורו תתן התורה סבה כי נזר שמן משחת אלהיו עליו ונאמר שהרצון בזה שלא יצא מן המקדש ויניח עבודתו מפני מת שימו' לו והנה אמרו ולא יחלל את מקדש אלהיו שלא יירא שיחלל מקדש אלהיו מפני היותו עובד אונן כי אין עבודתו מתחללת מפני האנינות לפי שהוא משוח בשמן המשחה ולזה ראוי שלא יתפעל כלל מכמו אלו הענינים באופן שתבלבל כונתו ואמנם הכהן הדיוט אם עבד אונן חלל וראוי שתדע כי אע"פ שכהן גדול אינו מחלל עבודה מפני האנינו' הנה הוא אסור באכילת קדשים באנינות כמו שהתבא' בפרשת שמיני מאמרו ואכלתי חטאת היום:
@13 **והוא אשה בבתוליה.** יקח למדנו מאמרו אשה כי אינו לוקח כי אם אשה אחת לא ב' נשים או יותר כי לעוצם קדושתו אין ראוי שישתדל ברבוי המשגל אבל יספיק לו ההכרחי לקיום המין ולמדנו מאמרו בבתוליה שלא תהיה בעולה כי שם הבתולה מורה על העדר הבעילה ממנה ולפי שהבעילה שהיא כחיית עליה היא משכב האדם הנה לא תאסר לכהן גדול מן התורה אם לא ישכב איש אותה אע"פ שכלו בתוליה לסבה אחרת:
@14 **אלמנה וגרושה וגו'.** למדנו אעפ"י שנתאלמנה מן האירוסין אסורה לכהן גדול והסבה בזה כי מפני שהיתה לאיש אחר אינו ראוי שיקח אותה כהן גדול לעוצם מדרגתו על שאר האנשים והנה רצון התורה בזה שאין ראוי שיקח אלמנה וכ"ש גרושה וכ"ש חללה וכ"ש זונה. וראוי שתדע שאם ארס אותה קודם שנתמנה כהן גדול מותר לו לנשאה שנא' לא יקח והרי לקחה קודם היותו כהן גדול:
@14 **כי אם בתולה מעמיו יקח אשה.** מגיד שאין נושא גיורת ומשוחררת ואף על פי שהיא בתולה:
@15 **ולא יחלל זרעו בעמיו למדנו.** שהוא מוזהר מלחלל זרעו באשתו הפסולה שיקח ויתבאר שהי' מתחללת בזה ממה שזכרנו במה שקדם וגם כן הנה מפני שזרעו מתחלל מפני היותו בה הנה ראוי יותר שתהיה היא חללה עד שאם לא נודה שתהיה היא חללה מפני זאת הביאה הפסולה לא יהיה לה טעם לזה הסדור הנזכר באלו הפסולות כי ידמה שהזונה היא היותר מגונה ואחריה החללה ואחריה הגרושה והנה החללה היותר מגונה מהגרושה היא אשר נתחללה מפני בעילה פסולה ואולם החללה שנולדה מפסולי כהנו' יותר מגונ' מהגרושה אבל הענין בהפך ולזה יתבאר מזה העניין שיש בכאן חללה היא מתחללת מפני הביאה הפסולה ומזה המקום יתבאר באופן מה שהכהן מוזהר מלחללה כי כבר הוזהר מלחלל מה שלא בא לעולם כ"ש שהוא מוזהר מלחלל זאת האשה הכשרה לכהונה ואפשר שיהיה הרצון באמרו בעמיו עם עמיו כי אות הבי"ת כבר ישתמשו בה בלשון בזה האופן ויתבאר מזה בביאור שהוא מוזהר מלחלל אשתו:
@15 **כי אני ה' מקדשו.** ר"ל הכהן הגדול ולזה ראוי שיתרחק מאלו הזווגים הפחותים:
@17 **איש מזרעך לדורותם אשר יהיה בו מום לא יקרה להקריב להם אלהיו.** ידוע כי מום יקרא אצל האנשים אי זה שנוי שיהיה ביציאת האדם בכמות או באיכות כאלו תאמר מי שצוארו קצר או מי שידמה לאלו השנוים אשר בבריאה אע"פ שאין בהן הפסד בפעולות הטבעיות והנה על כמו אלו המומין לוקה אם עבר וכבר יהיו באילו המומין מה שהתחלל העבוד' בעבורם והם הנזכרי' בפרטי' הבאים אחר זה כמו שיתבאר במה שיבא ויתבאר מאמרו איש שהקטן אינו ראוי להקריב ולא האש' ולא הטמטום ולא אנדרוגינוס:
@18 **כי כל איש אשר בו מום לא יגש להקריב.** ר"ל מום קבוע כי כבר זכר בפרטים הבאים אחריו מומין קבועים והם העור והפסח ואמנם בסוף העניין זכר מומין עוברים כגון גרב או ילפת וסמך לו כל איש אשר בו מום מזרע אהרן ההן לא יגע להקריב אשי הש' מום בו וגו'. והוא אזהרה לבעל מום עובר ולזה אמר מום בו להעיר שאינו נפסל אלא בעת שהמום בו לא אחר עברו והנה זכרה התורה המומים היותר קשים לפי שכבר יזכור שאם עבד הבעל מום יחלל עבודתו ולזה לא יהיה אלא בכמו אלו המומין החמורים ואם היתה כונת התורה שיהיה כל בעל מום מחלל עבודה היתה זוכרת המומים היותר קלים ומהן נלמד היותר חמורין ואמנם הבדילה החמורין לבאר שבהם ענין נוסף על שאר המומים והוא חלול העבודה וזה מבוא' מהשרשים הכוללים:
@18 **איש עור או פסח.** הנה העור הוא מי שנתעוור ראות עינו לאי זו סבה שתהיה ואע"פ שאין שנוי בתמונתו ומראהו והפסח הוא מי שיהיה פוסל בלכתו:
@18 **או חרו.** הוא מענין חרם שהוא מענין השחתה והפסד הוא מי שנפסד ממנו דבר מהדברים שיש להם רושם בפעולותיו והטבעיות כמו הענין במומין הקודמין לזה כאלו תאמר שיבשה אזהנו או מה שידמה לה:
@18 **או שרוע.** הוא שיהיה נוכף בו דבר יהיה בו הפסד מה בפעולותיו הטבעיות כאלו תאמר שיהיה לו שני שחוסין באוזן כי זה העניין ידמה שהוא משוער בטבע מצד הכמות והתמונה וכאשר נפסד הסדר ההוא לא תהיינה פעולות האבר הוא שלמות וזה מבואר למי שעיין בטבעיות ולזאת הסבה היו חלי מום כשיתבלבלו בעבורו הפעילות הטבעיות כי והוא גדר החלי כמו שהתבאר במלאכת הרפואה ולזה תמצא שאמר הנביא והבאתם גזול את הפסח ואת החולה:
@19 **או איש אשר יהיה בו שבר רגל או שבר יד.** למדנו שהשבר אינו פסל אלא בדברים שבגלוי כגון יד. ורגל:
@20 **או גבן.** הוא שיש לו שני גבינים על עינו ולזה יתבאר שאם אין לו גבים על עינו הוא בעל מום גם כן:
@20 **או דק או תבלול בעינו.** דק הוא מי שיש לו כתם לבנה על השחור שבעינו וזה מבואר מצד הוראת הגדר ותבלול שנתערב מהלובן בשחור ונכלל עמו ומזה יתבאר המומים שבעין הדומי' לו לפי מה שנתב' מהשרשים הכוללים:
@20 **או גרב.** הוא החכוך היבש:
@20 **או ילפת.** הוא חזזית המצרית והוא קשה הרפואה:
@20 **או מרוח אשך.** ר"ל שנתמעך אחד מאשכיו או נכתת ומזה יתבארו המומין אשר בכלי ההולדה הדומים להם:
@21 **כל איש אשר בו מום וגו'.** לפי שזכר אשי ה' שהן דברים נקטרים כאלו תאמר החלבים והקמץ והלבונה ולחם אלהיו שהוא נקטר. ר"ל מה שיקריב ממנו הנה נשפט כי על אלו יתחייב מלקות לפי שאין אחריהם עבודה אבל הם בעצמן גמר עבודה ואמנם לא יתחייבו מלקות על הפתיתה ועל הבלילה והתנופה ושאר מה שדומה להם כי הם אינן ראוין בזה הדין כמו אלו העבודות שהן גמר עבודה אמנם על זריקת הדם יתחייבו כי היא עבודה שאין אחריה עבודה אבל היא יותר מכוונת שבעבודו' כמו שהתבאר בענין הקרבנות ובכלל הנה על כל העבודות שהן גמר עבודה יתחייבו מלקות:
@22 **לחם אלהיו מקדשי הקדשים ומן הקדשים יאכל.** למדנו שהבעל מום חולק עם אחיו הכהני' בקדשי הקדשים ובקדשים קלים ר"ל עם אנשי בית אב:
@23 **אך אל הפרכת לא יבא ואל המזבח לא יקרב כי מום בו.** למדנו שהוא מוזהר מלבא אל הפרכת ומלהתקרב אל המזבח אף על פי שלא עבד. וראוי שנדע שהוא אינו מוזהר כי אם מהמזבח ולפנים כי משם יבאו להקריב בו כי שם פני המזבח כמו שביאר' במה שקדם ומזה הצד נמנע ממנו התקרב למזבח ולא נמנע ממנו הכנס למקדש:
@23 **ולא יחלל את מקדשי כי אני השם מקדשם.** ראוי שתדע שאין הכונה בזה חלול בית המקדש שאם היה הענין כן היה אומר אני הש' מקדשו ואולם אמר אני הש' מקדשים ר"ל הקדשים ומזה המקו' למדנו שהבעל מום מחלל עבודתו כשהי' מומו מכמו אלו המומי' החמורים שזכרה התורה כי לזאת הסבה בחרה הורה לזכור היותר קשה שבאלו המומין כמו שביארנו:
@26 **דבר אל אהרן ואל בניו וינזרו מקדשי בני ישראל.** לפי הענין ממה שנלוה לו למדנו שזה ההנזר הוא מעבוד עבודה וביאר שאם עבד חלל שנאמר ולא יחללו את שם קדשי אשר הם מקדישים לי וראוי שתדע שזה ענין הוא בכהן טמא לפי מה שיתב' ממה שנלוה לו אחר זה והנה יתב' שכבר יתחייב על זה החלול מיתה בידי שמים ממה שאמר אחר זה ומתו בו כי יחללוהו וזה שאם חייב מיתה על החלול אשר מפני אכלו הקדשים בטמאה כ"ש שיתחייב מיתה על החלול אשר מפני היותו עובד בטומאה וזה שאנחנו מצאנו בבעל מום שאיננו עובד ואוכל בקדשים כמו שקדם ולזה תהיה יותר חמורה העבודה מהאכילה וכבא יתבא' זה עוד מעצם העניין ממה שאמרנו בעניין הקרבנות:
@27 **אמור אליהם לדורותיכם כל איש אשר יקרב מכל זרעכם וגו'.** הנה זאת הקריבה היא לאכל וזה יתבאר ממה שזכר אחר זה בקדשים לא יאכל כי על הנגיעה לא יתחייב כרת כמו שיתבאר במעט עיון ממה שנזכר בפרשת צו והנה מה שאין לו מתירים יתיחסו עליו משקדשו ומה שיש לו מתירי' לא יתחייבו עליו עד שקרבו מתיריו וזה כי כבר אמר בפרשת צו בזה העניין והנפש אשר תאכל בשר מזבח הלשמים אשר לה' והוא הבשר שקרבו מתיריו כמו שאמר קודם זה והבשר כל טהור יאכל בשר מכלל שהוא מדבר בבשר שקרבו מתיריו וכן הדין בשאר קדשים אי זה שיהיו ולזה בא המאמר בזה הפסוק:
@27 **וטמאתו עליו.** למדנו שלא יתחייב כרת אלא כשהיתה טמאתו עליו בשלמות אבל אם התחיל לטהר מטמאתו כאלו תאמר שטבל הנה אין טמאתו עליו ולזה לא יתחייב כרת אבל הוא לוקח כמו שיתבאר מהשרשים הכוללים וכבר נתבאר שהטמא שטבל והוא מחוסר כפורים מוזהר מאכילת קדשים ממה שאמר ביולדת בכל קודש לא תגע ולפי שהתנה זה התנאי באכילה ולא בעבודה למדנו שבעניין האכילה הקלה התורה לטבול יום או למחוסר כפורים לא בענין העבודה שהיא חמורה ממנה וזה מבואר מהמקומות הכוללים:
@28 **איש איש מזרע אהרן והוא צרוע או זב בקדשים וגו'.** למדנו מזה הענין שהוא מדבר בתרומה לא בשאר קדשים ולפי שכבר ייחס הטהרה באכילתה להערב השמש כמו שזכר אחר זה למדנו שהטבול יום שהעריב שמשו אוכל בתרומה אף על פי שהו' מחוסר כפרה ואולם בשאר קדשים אינו אוכל מחוסר כפרה כמו שקדם והנוגע בכל טמא נפש הוא טמא מת והוא מטמא הנוגע בו כמו שיתבאר בפרשת פרה:
@28 **או איש אשר תצא ממנו שכבת זרע.** כבר נתבאר בפר' מצורע שהבעל קרי הוא טמא:
@29 **או איש אשר יגע בכל שרץ אשר יטמא לו.** הן הח' שרצים הנזכרים בפרשת שמיני או באדם אשר יטמא לו לכל טמא כמו בועל נדה ורוק הזב. והנוגע במשכבו ומושכו ושאר הטומאות לכללם אשר יטמא בהם האדם:
@30 **נפש כי תגע בו וטמאה עד הערב.** ר"ל שהיא טמאה לעניין אכילת תרומה עד הערב בהכרח וכדי שלא נבין שאחר הערב יהיה מותר באכילת תרומה אף על פי שלא טבל הוסיף לבאר זה ואמר ולא יאכל מן הקדשים כי אם רחץ את בשרו במים ובא השמש ואז יטהר לזה הענין. ר"ל אחר שקיעת השמש:
@31 **ואחר יאכל מן הקדשים כי לחמו הוא.** הנה נתן טעם בהיות מותר לאכל בתרומה תכף שהעריב שמשו ואף עלפי שהוא מחוסר כפרה לפי שזה הקדש הוא לחמו אשר הוא אוכל אותו תמיד ולזה לא החמירה התורה בו כחמר שאר הקדשים. ומזה המקום יתבאר שאין הרצון באמרו וטהר שיטהר במוחלט באופן שלא יהיה מחוסר כפר' שאם היה כן לא היה צריך לתת טעם אל היותו מותר לאכול בתרומה וזה מבואר מאד:
@32 **נבלה וטרפה לא יאכל לטמא' בה.** ירצה בזה בנבלת עוף טהור שהי' מטמאה בעת הכילה כמו שקדם והוצרכ' התורה להזהיר זה לפי שהכהנים הותרו באכילת חטאת העוף שאינה שחוטה ואולי יחשבו מפני זה שתהיה נבלת עוף טהור מותרת להם ולזה ביארה התורה שהם גם כן אסורין בה ומטמאין באכילתה:
@33 **ומתו בו כי יחללוהו.** למדנו שהזר יתחיי' מיתה בידי שמים בהיותו נהנה מתרומה בזה האופן:
@33 **ושמרו את משמרתי ולא ישאו עליו חטא ומתו בו כי יחללהו.** ר"ל שישמרו משמרת התרומה ויזהרו מאכילתה בטמאה וביאר שם ש'אם יאכלוה בטמאה יתחייבו מיתה בידי שמים לפי שכבר חללוה והורידוה מקדושתה ומזה יתבאר שעל תרומה טמאה לא יתחייבו מיתה בידי שמי' שהרי היא מחוללת:
@34 **וכל זר לא יאכל קדש.** ר"ל מי שאינו מזרע הרן:
@34 **תושב כהן ושכיר לא יאכל קדש.** הגיד בזה כי אף על פי שהתרומה היא לחמו של כהן הנה לא יותר לו להאכילה לעבדו שאינו קנוי לו קניין הגוף:
@35 **וכהן כי יקנ' נפש קניין כספו הו יאכל בו ויליד ביתו הם יאכלו בלחמו.** מגיד שכיון שנפשו קנוי לו באי זה אופן שיהיה הנה הוא אוכל בתרומה ומזה המקום יתבאר שאפילו בהמתו של כהן אוכלת בתרומה כי נפשה קנויה לו ועוד שאי לאומר שיאמר שיותר עבד כנעני לאכל בתרומה מצד מעלתו כי אין לו מעלה על התושב והשכיר אבל יהיה העניין בהפך כשהיה השכיר עבד עברי ואמנם הותרה לו אכילת תרומה מפני היות גופו קנוי וכן הענין בבהמה כי גופה קנוי. ומזה המקום יתבאר שהמאורסת לכהן אוכלת בתרומה מן התורה כי היא קנויה לו:
@36 **ובת כהן כי תהיה לאיש זר.** ר"ל שהיא מאורסת לא לכהן היא בתרומת הקדשים לא תאכל. הנה המורם מהקדשים הוא חזה ושוק ומגיד שהיא אסורה בו ויתבאר גם כן שהיא אסורה בתרומה ממה שיבא אחר זה הפסוק ועוד כי כבר שבה קני למי שאינו אוכל בתרומה והנה נכלל בזה גם כן הנבעלת לפסול לה כי היתה לאיש זר לה לפי משפטי התורה ויתבאר שהיא אסורה לאכל בתרומה לעולם כי לא הותרה לאכל בתרומה כי אם האלמנה והגרושה שלא היה בהויתה לאיש והוא אסור כמו שנתבאר בפסוק הבא אחר זה:
@37 **ובת כהן כי תהיה לאלמנה וגרושה וזרע אין לה.** ר"ל שאף על פי שנתקדשה לזר או נתאלמנה או נתגרשה ואין לה זרע ממנו היא מותרת לאל בתרומה ולזה יתבאר שלא היתה מותרת בה בעודה אסורה לו ושאינה חוזרת לחזה ושוק שהוא יותר חמור מתרומה ולפי שהזרע הפסול פוסלה מלאכל בתרומה הנה נלמד שהפסולה שיש לה זרע מותר לאכול בתרומה. ר"ל שהי הזרע ההוא מכהן הנה היא אוכלת בעבורו כי ההקש הוא אחד ואין הבדל בזרע בין שיהיה הזרע או זרע הזרע באי זה אופן שיהיה כי הכל יקרא זרעה בלשוננו כמו שיתבאר במקומות רבים ושמתי את זרעך כעפר הארץ וגו'. והנה הכונה בו זרע הזרע והנה יתבאר שהערל אסור בתרומה מפסח שהוא קל ונאסר עם זה הערל מאכילתו וזה יתבאר מהמקומות הכוללים:
@37 **וכל זר לא יאכל בו.** ר"ל בלחם רביה שהוא התרומה:
@38 **ואיש כי יאכל קודש בשגגה ויוסף חמישיתו עליו.** ר"ל שמי שיאכל תרומה מהזרים בשגגה הנה יוסיף עליה החומש שהוא רביע מה שאכל כמו שביארנו בפרשת ויקרא והנה השגגה היא כשלא ידע שהיא תרומה או שלא ידע עשה כי באלו הצדדים יקרא האדם שוגג בעשותו דבר מה שמוזהר מעשותו וזה מבואר מאד וראוי שתדע שהאכילה והשתיה והסיכה דינן אחד בזה העניין כי הכונה בזה היא ההנאה בגופו שיכלה גו התרומה בה והוא מבואר שהאכילה לא תהיה לפי הנהוג כי אם במה שראוי לאכילה מצד עצמותו ושיהיה ראוי לכהן להנות בה ואמנם שהוא מחוייב שיהיה ראוי לאכילה מצד עצמותו הוא מבואר מהשרשים הכוללים ואמנם שהוא מהויי' שיהיה ראוי לכהן להנות בו שנאמר' ונתן לכהן את הקדוש מכלל שהיא היתה קנין לכהן הזה ולזה צוה להשיבה לו ולו היתה אסורה בהנאה הנה אינה קנין לו ולפי שהאכילה לא תהיה לפי הנהוג אלא במה שיאכל האדם עד שיהיה שבע לא במה שיאכל אחר שהוא קץ במזונו מפני שבעו הנה לא יוסיף האדם חומש אם אכל תרומה בזה האופן:
@38 **ונתן לכהן את הקדש.** למדנו מזה שמה שישיב לכהן הוא קדש ודינו כדין התרומה ומזה יתבאר שהחומש ג"כ הוא בתרומה ולפי שאמ' ונתן לכהן שהרצון בו הכהן הידוע הנה הוא בואר שהוא רמז בזה אל הכהן שהיתה ממנו התרומה שאכל והנה יתבאר מזה שהקרן יחוייב שישיב לכהן ההוא שהוא הקודש שאכל ואמנם החומש יתנהו לכל כהן שירצה:
@39 **ולא יחללו את קדשי בני ישראל.** ר"ל שלא יוציאו לחולין התרומה בשיאכלו זרים ממנה או באיזה אופן שיהיה כאלו תאמר כשתיה או בסיכה ולפי שכבר אמר בתרומה קודם זה:
@39 **את אשר ירימו לה'.** הנה יתבאר מזה שאף על פי שלא הרימו תרומה עדיין אם אכלו מן הטבל הראוי להרים ממנו תרומה יתחייבו מיתה לפי שהם חללו מה שבו מהתרומה ולפי שהתורה לקחה החמור שבזה הסוג והיא חייבה בו מיתה והוא הטבל שתרומתו בתוכו הנה יתב' מהשרשי' הכוללים שהטבל שנטלה תרומתו ולא מעשרו הוא באזהרה ולא במיתה:
@40 **והשיאו אותם עון אשמה באכלם את קדשיהם.** הרצון בעון ענש ואשמה שממה כטעם תאשם שומרון שהוא מעניין שממה ור"ל שכבר ישיאו עצמם עונש של שממה באכלם את קדשיהם כי כבר נתחללו כמו שקדם ויהיה עונש עליהם מיתה כי אני הש' מקדשם ולזה יחטא בזה האופן מי שיחללם:
@42 **איש איש מבני ישראל ומן הגר בישראל.** הוא הגר צדק שהוא כישראל לעניין מצות התורה כמו שנזכר בתורה פעמים:
@42 **אשר יקריב קרבנו לכל נדריהם ולכל נדבותם.** הנה הנדבה הוא שיקדיש הבהמה ויאמר הרי זו עולה והנדר שיאמר הרי עלי עולה ואח"כ יפרישנה:
@43 **לרצונכם תמים זכר בבקר בכבשים וגו'.** הנה לא זכר העוף לפי שאן אלו המומין שזכר נוהגין בו ולזה לא נאמר בו תמים והנה יתבאר מהשרשי הכוללים שהוא לא סלק מן הדין כי אם כמו אלו המומין ואולם המומין החמורין מהן כמו מחוסר אבר או מה שישימהו במדרגת הטרפה שהוא אסור אפילו להדיוט הוא פסול בקדשים. הלא תראה כי גם מהמותרין באכילה לא התירה התורה להקריב כי אם התורים ובני היונה:
@44 **כל אשר בו מום לא תקריבו.** לפי שכבר תקרא הקרבה הקדשת הבהמה בנדבה או הפרשת הבהמה לשלם הנדר והוא מבואר מצד הוראת הגדר וממה שנזכר בפרשת ויקרא מזה הנה יתבאר מזה שהמקדיש בהמה בעל מם למזבח עובר בלאו:
@45 **ואיש כי יקריב זבח שלמים להשם.** הבדילו מהעולה לפי שאין התנאי בו שיהיה זכר ואולם לענין המומין דינן שוה:
@45 **לפלא נדר או בנדבה.** ר"ל שזאת ההקרבה היתה על הנדר שפרש או שהקדיש הבהמה לנדבה להיות שלמים:
@45 **תמים יהיה לרצון.** מצות עשה הוא שיהיה תמים ובזה האופן ישלם בו הרצוי:
@45 **כל מום לא יהיה בו.** למדנו מזה שאפילו שאחר שהקדישו מוזהר שלא להטיל בו מום והוא מצות לא תעשה:
@46 **עורת או שבור.** כבר התבאר עניינים במומין הקודשים ושם יתבאר שהשבירה לא תיפסל אלא כאברים הנגלים:
@46 **או חרוץ.** מעניין חרץ כאלו תאמר שנסדק עורו אם עצם מעצמיו והוא מתייחס לשבור וסמך לו ולזה לא ינהג אלא במקומות הנגלים כמו הענין בשבור:
@46 **או יבלת.** הוא בלבן העין לפי מה שיורה עליו הגדר שאם היה בשחור הנה תהיה עורת ולפי שאלו המומין שזכר בפרט הם מומין קבועים למדנו מזאת היבלת היא שיש בה שער שאם לא היה בה שער הוא הום מום עובר לפי מה שהתבאר בחפוש:
@46 **או גרב או ילפת.** כבר נתבארו במומי האדם:
@46 **לא תקריבו אלה להש' ואשה לא תתנו מהם על המזבח להש'.** לפי שכבר קדמה האזהרה מלהקדיש בעל מום הנה תהיה האזהר' בזה המקום באמרו לא תקריבו שלא יזרק דמם על המזבח ולזה סמך לו האזהרה מהקריב אשה מהם על המזבח להשם כי הזריקה מכשרת האשה לתתו על המזבח והנה הזהיר על זה בשלמי' וכ"ש בעולה ושאר הקדשים החמורים מהם:
@47 **ושור ושה שרוע וקלוט נדבה תעשה אותו ולנדר לא ירצה.** הנה השרוע הוא מי שהוא יתר אבר כאלו תאמר שיש לו חמשה רגלים וב' שחוסין של אזן. וקלוט הוא שפרסתו עגולה כפרסת החמור ואמרו נדבה תעשה אותו אין הרצון בו להקדישו למזבח כי כבר קדמה האזהרה בזה ואמנם הרצון בו להקדישו לבדק הבית שהוא קדושת דמים ואולם מה שאמרו ולנדר לא ירצה שמורה לפי מה שביארנו שאם נדר בהמה לבדק הבית מהבהמות הראויות למזבח כמו שו ושה הנה אין ראוי שיפריש על זה הנדר בהמ' בעלת מום ולפי שאין בזאת הפרשה נזק לבדק הבית ועם זה הקפידה בו התור' למדנו שכר הקפידה בזה מצד המנע הקרבתה למזבח ולמדנו מזה שהמקדיש לבדק הבית דבר ראוי למזבח יחוייב שיהיה קרב למזבח:
@48 **ומעוך וכתות ונתוק וכרות.** הנה מעוך הוא שנמעכו אשכיו או אחד מהם וכתות שנכתתו אשכיו או אחד מהם ונתוק וכרות הוא שנתק אחד מאשכיו או נכרת וכ"ש אם נתק הגיד או נכרת כי בזה השחתה יותר עצומה לכלי ההולדה:
@48 **לא תקריבו ליי' ובארצכם לא תעשו.** לפי שסמכה אל אזהרת השחתת כלי ההולדה במוחלט שהיא אזהרה לכל ישראל הנה תהיה זאת האזהרה גם כן לכל ישראל ואם היא להזהר מהקדיש בעלי מומין למזבח או להזהיר משחיטתם שהיא כשרה בזר ולפי שכבר הזהיר' התורה על שחיטתם בביאור בפרשת שופטים שנאמר לא תזבח ליי' אלהיך שור ושה אשר יהיה בו מום כל דבר רע הנה לא ידמה שתהיה זאת האזהרה מהקדשים וכפל האזהרה בזה המקום שלא לחשוב שלא תהיה זאת האזהרה כי אם בעולה לא במה שלמטה ממנה בקדשים והנה אמרו ובארצכם לא תעשו אי אפשר שיהיה הרצון בו שלא תנהג זאת האזהרה כי אם בארץ ובשור ובשה. וזה כי לסבה בעינה שימנע זה העניין בשור ושה ימנעו בשאר בעלי חיים כי אין לאומר שיאמ' שכבר נמנע זה בשור וזה מפני שאפשר להקריבו למזבח שהרי בארה התורה שכבר ימנע להטיל מום בקדשים לא בחולין ואם היתה הכוונה שימנע להטיל מום בחולין במוחלט הנה היה ראוי שתזכור זה בתורה במומין האחרים שאין בהם מהגנות וההפסד אצל הטבע כמו מה שיש באלו המומין ומהם נלמד שכן הענין בשאר המומין והנה גם כן זרות הפעל זה בגנותו אין בו רושם בהעשותו בארץ או בחוצה לארץ ולזה יהיה הרצון באמרו ובארצכם לא תעשו שלא תחשבו שיהיה המנע זה מצד מה שהוא ליי' אבל אם לא היה ליי' יותר זה הפעל לעשות שאפילו חוץ מבית המקדש שהוא לכם ואינו ליי' אתם מוזהרים מעשות זה הפועל המגונה לפי שיש בו השחתה לכלי ההולדה אשר שם השם יתעלה בב"ח לשמור מינו ולזה יהיה נכלל בזה חוצה לארץ וזה מבואר מאד כי אין לצאת המצוה התלות בארץ:
@49 **ומיד בן נכר לא תקריבו את לחם אלהיכם מכל אלה.** הנה לכם ה' יתעלה הוא העולה כמו שאמר קרבני לחמי וגו'. וראוי שיבאר שאין מקבלים מהגוי כי אם עולה כי אינו במדרגה שיתכן שיקריב שלמים שיאכל הוא וה' ית' על שלחן אחד ואין ראוי ג"כ שיקריב קרבנות באים על חטא כי אינו מחוייב בהם ואולם העולה נקבל ממנו לפי שהיא באה בנדר ונדבה:
@49 **כי משחתם בהם מום בם לא ירצו לכם.** ר"ל שבהם דבר נשחת והוא מום בהם ולזה לא יהיה לרצון אם יקריבום לשם יתע' ולפי שכבר אמר בכללות כל אשר בו מום לא תקריבו למדנו שאי זה מקום שיהיה בבהמה ממה שנקרא מום בה לפי הוראת הגדר אע"פ שהו' מום עובר הוזהרנו מהקרבתה ליי' וכבר התבאר בפרשת שופטים שאפילו בזביחה הוזהרנו אפי' במום עובר שנאמר כל מום רע כ"ש בזריקת דמים ובהקטרה. וראוי שתדע שהטומטום והאנדרוגינוס הם בעלי מומין מצד הפסד כלי ההולדה בהם וזה מבואר בטומטום וכן האנדרוגינוס אין בו כח אל ההולדה כמו שיתבאר לי שעיין בטבעיות עיול שלם עם שאינו לא זכר ולא נקבה והתור' דקדקה בקרבנות בקצתם שיהיה זכר ובקצתם שיהיה נקבה וכאשר לא דקדקה התורה בזה לפי זה הענין מה שהו' זכר או נקבה לא מה שאינו לא זכר ולא נקבה ויתב' שהרובע והנרבע והנעבד והממית את האדם פסולים למזבח לפי שכבר אסרה התורה אתנן זונה ומהיר כלב כ"ש אלו שנעשה הגנות בעצמם:
@51 **שור או כשב או עז.** למדנו שלא יותר למזבח אלא מה שהוא ממין מיוחד לא מה שהוא מורכב משני מינים כי הוא אינו שור ולא כשב ולא עז וכבר יתבאר שלא יותר אם לא היה דומה למינו והמשל שאם היה בכאן עז והוא דומה לכבש הנה לא יותר למזבח כי הוא אינו כבש ולא עז לפי שהוא דומה לכבש:
@51 **כי יולד.** למדנו שלא יותר למזבח אלא הנולד כמשפט לא שקרעו את אמו והוציאוהו דרך דופן כי אין זאת הלידה טבעית ויורה זה על חסרון בטבע בנולד ולזה לא תתחזק לצאת דרך הרחם עם שהוא אפשר שלא נשלמה הויתו עדין אבל התעורר לצאת קודם זמנו לסבה מה כאלו תאמר לחסרון המזון או למה שאפשר שיהיה סבה בזה והם הסבות אשר אפשר שינתנו בהפלת העובר:
@51 **והיה שבעת ימים תחת אמו.** למדנו מזה שראוי שתהיה לו אם ואז יותר למזבח לא אם נשחטה אמו קודם שנולד עם שאין זו לידה לפי הוראת הגדר ובכלל הנה לסבה בעינה אשר נמנעה הקרבת יוצא דופן תמנע הקרבת היתום ואין ראוי שנבין שיחוייב שתהי' לו אם שבעת ימי' כי אין בחיות אחר לידותו רושם בשלמו' הילוד כי כבר אפשר שיינק מבהמה אחרת ולא יהיה בזה לו שום הפסד:
@51 **ומיום השמיני והלאה ירצה לקרבן אישי ליי'.** דקדקה התורה בזה לפי שלא יתבאר לנו מהנולד שלא יהיה נפל אף על פי שנולד באופן שלם אם לא עברו עליו ז' ימים ולזה לא יותר להקריבו קודם זה הזמן:
@52 **ושור או שה אותו ואת בנו לא תשחטו ביום אחד.** לפי שלא אמר ליי' כמו שאמר קודם זה ואחר זה למדנו שזאת האזהרה נוהגת בחולין ובמוקדשין ולפי שאמר בכאן שה תמורת מה שאמר קודם זה או כשב או עז למדנו שהיא נוהגת בכלאים כאלו תאמר שה הבא מכבש ועז ויתבאר שאינו נוהג אלא בבהמה טהורה שנאמר שור או שה ולפי שאמר לא תשחטו למדנו שלא יעברו על זאת האזהרה אם לא נשחטו שניהם לא אם מת אחד מהם באופן אחר או שניהם וידמה שלא יהיה זה הדין נוהג אלא באם ובנה לא באב ובנו כי אינו מפורסם בכמו אלו הב"ח מי אביהם ולא נהגו האנשים ליחס הנולדים האלו לאביהם אבל לאמם כי היא לבדה תשתדל בהזנתם ובגדולם וכבר יסופק אם ינהג זה הדין גם כן בזכרים כשיודע שהוא אביו לפי שכבר הוציאה התור' זה בלשון זכר ולזה לא יתחייב מלקות אם נשחט האב ובנו ביום אחד אף על פי שהוא ידוע שהוא אביו:
@53 **וכי תזבחו זבח תודה ליי' לרצונכם תזבחו.** ר"ל שתהיה כוונתכם להתרצות בזה הוכח לשם יתעלה ולזה יחוייב שיהיה זה לכונה רצויה וברצון ולא באונס:
@54 **ביום ההוא יאכל.** הזהיר שלא יותירו מבשר זבח התודה עד הבוקר וכ"ש מהחלבים ומקדשי הקדשים וכבר הזהיר בזה בחלבים ביותר קל מהם והוא חלב השלמים שנאמר ולא ילין חלב חגי עד בקר:
@55 **ושמרתם מצותי ועשיתם אותם אני יי'.** ר"ל אף על פי שיכריחו אתכם לעבור על דברי להפר את בריתי:
@56 **ולא תחללו את שם קדשי.** ר"ל שלא תקלו בי ותחללו שמי לעבור על דברי לשמוע אל המכריח אתכם לעבור עליהם ליראתכם ממנו כי בזה מהחלול הנפלא אפילו למלך בשר ודם עד שכבר תמצא שיתירו מסירת עצמם להריגה להשמר שלא ימרדו בו ליראת המכריח אותם לבזו' המלך ההוא:
@56 **ונקדשתי בתוך בני ישראל.** זה הקדוש הוא שיתיר עצמו למיתה מיראתו מעבור על דבר השם יתעלה כמו שנפרסם מענין חנניה מישאל ועזריה אלא שזאת המצוה לא יתחייבו בה אם לא היו שם מאנשי האמונה מה שיראו זאת הקדושה שנאמר בתוך בני ישראל והוא מבואר שאמרו בתוך בני ישראל הוא מעיר על הקבוץ ר"ל על הקהל והוא מבואר מצד הוראת הלשון ולזה לא יחוייב להתיר עצמו למיתה על זה אם לא היו שם עשרה מישראל כי הוא הקבוץ הראשון וראוי שנדע שזה הדין יהיה כשתהיה כונת המכריח על זה להעביר אותו על מצות השם יתע' כדי שימרוד בו ולזה סמך זה למה שאמר ולא תחללו את שם קדשי ואולם אם לא כיון חלל הש' יתעלה כבר יותר לו לעבור על מצות התורה להציל עצמו מהמיתה אלא אם היתה העברה ההיא ע"ז או גלוי עריות או שפיכות דמים כמו שהתבאר בשרשים הכוללים:
@56 **אני יי' מקדשכם.** ר"ל שהשם יתעלה מקדש ישראל ומבדיל אותם לעבודתו בזאת התורה השלמה ולזה ראוי שנשמר בכל הפנים שאפשר שלא יקלו אנשי התורה לעבור עליה כי זה אולי יהיה סבה שתסור זאת התורה מישר' במוחלט וזה מבואר מאד עם מה שקדם מהדברים:
@57 **המוציא אתכם מארץ מצרים.** ר"ל שאני השתדלתי בזה האופן הנפלא להוציא אתכם מארץ מצרים עם רבוי הנפלאות והמופתים כדי שתוכנו לקבול התורה באופן שאהיה לכם לאלהים כי בזה תגיע לכם ההצלחה האנושית עם שבזה האופן תדבק בכם השגחתי ותשמרו מהרבה מהרעות הנכונות לבא עליכם ולזה ראוי לכם שלא תאבדו זאת המתנ' הנפלאה אשר נתתי לכם אשר בה אהיה לכם לאלהים ולמנהיג והיא התורה:
@59 **דבר אל בני ישראל ואמרת אליהם מועדי יי' אשר תקראו אותם מקראי קדש.** ראוי שתדע שהמועדים המיוחסים היותם מקראי קדש לקריאתנו הם שאר המועדים זולת השבת כי השבת הוא מקרא קדש מצד עצמותו אין לנו התחלה בהיותו נקרא ביום שהוא בו. ואולם שאר המועדים הם תלוים בעבור השנה והחדש אשר ענינם מסור לב"ד כמו שביארנו בפרשת בא אל פרעה ולזה תמצא שאמרה התורה זה הענין בכללות מפני שאר המועדים לא מפני השבת לזה לא יאמר בשבת דבר אלא שהוא מקרא קדש כי הוא מקרא קדש מצד עצמותו וכאשר התחיל לזכור שאר המועדים הקדים ואמר אלה מועדי יי' אשר תקראו אותם במועדם כי קריאתם במועדם מסור לנו כמו שביארנו במה שקדם:
@60 **כל מלאכה לא תעשו.** הוא כולל מהמלאכות שהם לצורך אוכל נפש ושאר המלאכות שהם מלאכת עבודה וכבר בארנו במה שקדם שכבר יתחייב בשבת על כל מלאכה ומלאכה אף על פי שנכללו כלם בלאו אחת לפי שהתורה בארה שכבר נכלל בזה הלאו מה שיתחייב עליו בייחוד והיא ההבערה שנאמר לא תבערו אש בכל מושבותיכם ולזה יתבאר שכבר יתחייב על כל אחת משאר המלאכות כמו שהתבאר מהשרשים הכוללים:
@60 **שבת היא ליי' בכל מושבותיכם.** לפי שלא זכר בכאן דבר שלא יהיה נוהג בכל מושבות אמר בכל מושובותיכם לא שלא יהיו שאר המועדים גם כן נוהגים בכל מושבות אלא שכבר זכר מהם מה שאינו נוהג בכל מושבות והם הקרבנות:
@61 **אלה מועדי יי' אשר תקראו אותם במועדם.** למדנו מזה שמה שנקרא מהם הוא קיים איך שיהיה. ר"ל מה שיקראו ב"ד הגדול כי הדבר מסור להם ואף על פי שטעו בקריאתם אין לנו אשם בזה וכבר בארנו בפרשת בא אל פרעה איך תהיה זאת הקריאה ושהיא באמצעות הראייה. ולזה אפשר שיקרא בזה הטעו' שלא יראה הירח בזמנו אם בסבת אידים או בסבת הרים מונעים מראיית הירח ולפי שכבר אמר אשר תקראו אותם במועדם והקריאה הזאת היא באמצעות הראיי' למדנו שהרואין הירח יותר להם ללכת לב"ד להעיד שכבר ראוהו אפילו בשבת כדי שיקדשו החדש בזמנו כי התורה צותה שיקדשו בזמנם ולפי שזה הענין יהיה בקבלת עדות ובדרישה ובחקירה אם דבריהם אמיתיים לפי מה שאפשר אם מצד הסכמת העדים קצתם לקצת אם מצד הסכמת מה שיראה מחכמת הכוכבים למה שהעידו וכמו אלו הפעולות לא יורגש העשותם כי אם ביום הנה לא תהיה זאת הקריאה כי אם ביום קודם עבור יום החדש כי לא יתכן שיקדשוהו אחרי עברו וזה מבואר בנפשו ולזאת הסבה ארז"ל שאף על פי שראוהו ב"ד וכל ישראל בליל שלשים ולא הספיקו לומר מקודש ביום השלשים עד שחשכה הרי החדש ההוא מעובר לפי שאין מקדשין את החדש אחר עבור יומו ותימה על הר"ם ז"ל שכתב מה שהוא סותר זה הדעת מפני מה שאמרו בראשון מראש השנה מאיימין את העדים על החדש שנראה בזמנו וכו'. וכבר יתבאר שיפורש המאמר ההוא באופן בלתי סותר למאמר הראשון והוא גם כן פסק זה המאמר הראשון ולזה היו דברי' סותרים קצת מקצת או יהיה זה טעות נפל בספרים והנה בקדוש החדש תלוי קדוש המועדי' ולזה יהיה הקדוש הרמוז בזה הפסוק קדוש החדש לא קדוש המועדים כי אחר שנקבע החדש כבר יודע מעצמו המועד אשר באותו כאלו תאמר שהוא יום העשירי או יום חמשה עשר לחדש ההוא בחדש הראשון הוא ניסן כמו שביארנו במה שקדם בפרשת בא אל פרעה:
@62 **בין הערבים פסח ליי'.** ר"ל ששחיטת הפסח הוא בין הערבים והוא מחצות היום ואילך כמו שבארנו בפרשת בא אל פרעה:
@63 **שבעת ימים מצות תאכלו.** הכונה בזה שיהיה מה שיאכלו מהלחם באלו השבעה ימים מצה לא חמץ לא שיהיה מצות לאכול מצה כל אלו הז' ימים ולזה אמר במקום אחר מצות יאכל שבעת ימים שהוא מורה שזאת האכילה היא רשות וכבר בארנו זה בשלמות בפרשת בא אל פרעה:
@64 **כל מלאכת עבודה לא תעשו.** כבר בארנו ענינה בפרשת בא אל פרעה:
@65 **והקרבתם אשה ליי' שבעת ימים.** כבר נתבאר בפרשת פנחס שזה האשה הוא עולה פרים בני בקר שנים ואיל אחד ושבעה כבשים. וזה יהיה מוסף היום בכל יום מאלו הימים ולפי שאמר בזה המקום אשה ליי' ולא ביאר בזה יותר למדנו שהמספר הנאמר בזה בפרשת פנחס הוא למצוה לא לעכב והמשל שאם אין להם שנים פרים מקריבים אחד אין להם פרים מקריבים כבשים ואיל אין להם איל מקריבים כבשים אין להם ז' כבשים מקריבים ששה שנאמר והקרבתם אשה ליי' מכל מקום:
@67 **כי תבאו אל הארץ אשר אני נותן לכם וקצרתם את קצירה.** למדנו שאין העומר בא אל מהקציר שבאר ישראל והוא מבואר מצד הזמן שה הקציר הוא קציר שעורים כי קציר החטים לא יהיה בארץ ישראל בזה בזה הזמן:
@67 **והבאתם את עומר ראשית קצירכם אל הכהן.** למדנו מזה שזה העומר יחייב שיהיה ראשית לכל הנקצרים ולזה הוא מבואר שאסור לקצור מה שהוא ראוי להביא ממנו עומר קודם קצירת העומר אלא אם היה זה למצוה שנאמר ראשית קצירכם אל הכהן לא ראשית קציר מצוה:
@68 **והניף את העומר לפני יי' וגו'.** כבר ביארנו במה שקדם שהתנופה הוא למזרח מוליך ומביא מעלה ומוריד והנה זאת התנופה איננה לעומר בעצמו כי כבר קדם בתנופה שהיא לדבר המתוקן להקריבו כאלו תאמר אשי החלבים ומה שידמה להם מה שנזכר בו התנופה ואולם היא לסולת העומ' כשהו' באופן מוכן להקריבו וכבר התבאר בפרשת ויקרא איך נעה מנחת העומר והוא מה שאמר ואם תקריב מנחת בכורים וזה מבואר שהמאמר בו במנחת העומר היא מנחת בכורים וזה היא שראשונה לכל המנחות הבאות מן החדש ואין לאומר שיאמר שיהיה הרצון בה ב' הלחם הבאים בחג השבועות שנקראו מנחת בכורים במה שאחר זה כי לא יצדק בה מה נאמר בזאת המנחה בפרשת ויקרא וזה כי היא בלתי שתעשה חמץ כי כבר יקריבו ממנה ליי' מגרש' ומשמנה על כל לבונתה וכבר נאמר שם במאמר כולל כל המנחה אשר תקריבו ליי' לא תעשה חמץ. ואמנם שתי הלחם הבאי' בעצרת הם חמץ כמו שיתבאר בזאת הפרשה ולזה הוא מבוארת שזאת המנחה היא מנחת העומר ושהיא באה מצה ואופן מעשיה היא באופן שנתבאר שם והוא שקולין את התבואה אשר בעומר ההוא באש כדי שייבש ויתכן לטחון אותו ולקחת הסלת ממנו וטוחנים אותו בריחים של גרוסו' כדי שתהי' הסולת יותר יפה וזהו אמרו גרש כרמל ואחרי כן יבדרו הסלת היותר יפה ממנה בכל הפנים שאפשר ויקחו ממנו עשרון שהוא השעור הקטן אשר ממנחות לפי שלא נזכר בתורה לזאת המנחה שעור ויבללו אותו בשמן בקטן השעור הנזכר בתורה והוא לוג כי לא נזכר שם שעור לשמן אשר יבללוהו בו ונותנין עליו קומץ לבונה ומניף הכהן זאת המנחה במזרח ומגישה למקום הגשת המנחות וקומץ מגרשה ומשמנה על כל לבונתה כמו שנזכ' בפרש' ויקרא ומקטיר זה הקומץ והשאר נאכל לכהנים ונאפה מצה כמשפט המנחה שהקריבו ממנה ליי' עם שזה העניין הוא ביום השני של פסח שאי אפשר לאכול חמץ ולמדנו שהתנופה היא בכהן שנאמר יניפנו הכהן אבל קודם התנופה כמו הקצירה וההבאה כשר בכל אדם ולמדנו שהבאת העומר היתה ביום שני של פסח שנאמר ממחרת השבת וזה השבת הוא בהכרח אם יום ראשון של פסח אם יום שביעי כי לכל אחד מהם שבת כמו שנזכ' במה שקדם וכבר יתבאר ממה שאמר בספר יהושע שהוא ממחר' יום ראשון של פסח שנאמר ויאכלו מעבור הארץ ממחר' הפסח מצות וקלוי וכבר עשו הפסח בי"ד יום לחדש בערב כמו שנזכר שם והנה היה יום י"ו בניסן מחרת הפסח כי בליל ט"ו היה נאכל והוא ממחרת השבת הנזכר בזה הפסוק ולזה הזכיר כי ביום ההוא אכלו מצו וקלוי כי כבר נאסר להם קודם הנפת העומר לאכול מהחד' לחם וקלי וכרמל כמו שיתבאר בזאת הפרשה והנה חוייב שיהיה מצות לפי שכר היה אסור להם לאכול חמץ וזה ג"כ לאות כי אמרו ממחרת השבת ירצה בו מחרת יום ראשון של פסח ולפי שהנפת העומר הוא ממחרת השבת והספירה שזכר אחר זה היא גם כן ממחרת השבת והיא גם כן מהחל חרמש בקמה למדנו שהקצירה לא תהיה אלא אחר יום ראשון של פסח ולפי שזאת המנחה קבוע זמנה והוא ממחרת השבת למדנו שזאת הקצירה דוחה שבת. ולפי שהראוי בספירה שתהיה בהתחלה אחרי הדבר הנספר לא באמצעם ויהיה התחלת הימים לפי התורה בתחלת הלילה למדנו שמצות הקצירה היא בתחלת ליל י"ו בניסן ולפי שאמר מהחל חרמש בקמה למדנו שמצות העומר לבא מן הקמח וכן מצותו להביאו מן הלח ולזה צותה התורה שיביא קלוי באש ליבשו אלא שהוא מבואר ממה שנאמר בזאת הפרשה שאם לא מצאו מהקמה אפשר להביא מהעמרים אף על פי שהם יבשים שנאמר והבאתם את עומר ראשית קצירכם כיון שהוא ראשית הקצירים הנה אין קצירתו בי"ו בניסן מעכבת:
@69 **ועשיתם ביום הניפכם את העומר כבש תמים בן שנתו וגו'.** זה הקרבן יתר הוא על קרבן מוסף היום והיתה מנחתו כפל מנחת הכבש ולפי שאמר בלולה בשמן למדנו שהיא תהיה בלולה בשמן שהגבילה תורה לשני עשרונים והיא שלישית ההין ואמנם נסכו לא נכפל לפי מה שיתבאר מענין הנסכים בפרשת פנחס ושם נבאר בג"ה איך תהיה זאת ההקרבה לנסכים וראוי שתדע שהסלת הזאת הבלולה בשמן היתה כלה נשרפת על מזבח העולה שנאמר אישי ליי' ואולם היין אסור לנסכו על מערכת האש שלא יבכה אש המזבח אבל הכהן יוצק משם על היסוד למקום שיהיה נפשך בו שירי הדם והיה היין מסיר עפוש הדם ההוא שנאמר בפרשת פנחס בקדש הסך נסך שכר ליי' ולזה לא יחוייב שיהיה נשפך על המזבח':
@71 **ולחם וקלי וכרמל לא תאכלו וגו'.** הזהיר מאכילת לחם מהתבוא' חדשה ולא קלי ולא כרמל והוא הגרש. ר"ל שנפרך בריחים של גרוסות קודם הקרבת העומר ולפי שבא זכר האזהרה אחר זכרונם למדנו שהם שלשה לאוין כי אמרו לא תאכלו שב לכל אחד מהם ביחוד לא למה שיכללם ולו היתה האזהרה ראשונה היינו אומרים שהכל לאו אחד אלא שזכרה התורה הפרטים מפני שלא נמצא שם אחד שיכללם וזהו אחד מהשרשים הכוללים ולפי שאמר עד עצם היום הזה למדנו שמתיר החדש אף על פי שלא הביאו מנחת העומר יותר החדש תכף ביום ההוא בעצמו ואם לא יביאו מנחת העומר לא יותר עד עבור י"ו בניסן שנאמר עד עצם היום הזה והוא מבואר שהיום הזה בכלל האסור שאם היה מותר החדש בהגיע יום הנפת העומר הנה יהיה החדש מותר קודם הנפת העומר וזה הפך מה שאמרה התורה ולפי שנא' שאיסור החדש נוהג בכל מושבות למדנו שאיסור החדש נוהג מן התורה בין בארץ בין בחוצה לארץ והוא מבואר מזה המקום שהעומר מתיר החרש בכללו אע"פ שלא נקצר אבל הוא מחובר בקרקע והוא מבואר שאין העומר מתיר עד שלא היה מחובר לקרקע בעת הנפת העומר וצמח אחר זה כי אינו מתיר הוא כי אם הנקצרים והעומדים ליקצר שהחלו בצמיחה אף על פי שלא נשלמה ולזה יתיר העומר קציר החטים להדיוט אף על פי שהוא נקצר זמן ארך אחר הנפת העומר:
@72 **וספרתם לכם ממחרת השבת וגו'.** למדנו שיום הבאת העומר בכלל הימים הנספרים כי ממחרת יום ראשון של פסח יחל המספר והנה שבע השבתות הם שבעה שבועות של ימים שהם מ"ט יום כבר אמר תמורת זה בפרש' ראה שבעה שבועות תספור לך ואמר תמימות תהיינה כדי שלא נחשוב שיהיה הרצון בשבתות האלה שבת בראשית כי כבר יקרה שיהיו ז' מאלו השבועות בפחות משבעה שבתות ולזה בארה התורה שאלו השבע שבתות יהיו מ"ט יום ולזה אמר עד ממחרת השבת השביעית תספרו חמשים יום. ר"ל עד ממחרת השבוע השביעי תספרו שהוא יום החמשים והנה אינו בכלל המספרים כי כבר אמר שבע שבתות תמימות תהיינה שבעה שבועות תספור לך. וכבר נלמד זה גם כן מהיובל שנמנה תשע וארבעים שהם שבע שבתות שנים ואחד נקדש שנת החמשים כמו שנתבאר בפרשת בהר סיני ובזה נמנה בכאן מ"ט יום ונקדש יום החמשים והו' חג השבועות ולמדנו מזה שמצוה למנו' השבתו' והימים ואחשוב ספירת השבועות היא שנמנה שבוע א' בהגיע שבעת ימים ושני שבועות בהגיע י"ד יום וכן על זה הדרך עד שיהיו שבעה שבועות ואמנם במה שבין השבועות אין ראוי לספור שבועות כאלו תאמר שכאשר היו עשרה ימים אין ראוי לשוב לספור שהוא שבוע אחד ושלשה ימים כי המספר השבועות ראוי שיהיה בדרך המספר לא שימנה השבוע האחד ויחזור וימנהו ששה פעמים וזה מבואר בנפשו כי המספר לא יהיה בזה האופן:
@73 **עד ממחרת השבת השביעית תספרו חמשים יום.** ר"ל עד ממחרת השבועה השביעית תספרו שהוא יום הנ' ואז ביום החמשים תקריבו מנחה חדשה ליי' או יהיה הרצון באמרו חמשים יום עד חמשים יום כמו ארבעים יכנו שהרצון בו עד ארבעים יכנו כמו שנבאר שם בג"ה ובכא יום החמשים תקריבו מנחה חדשה ליי' ולפי שהוא קרא זאת מנחה חדשה למדנו שהיא חדשה למנחות החטים לא לכל המנחות כי כבר קדמה לה מנחת העומר ולמדנו מזה שאין ראוי להביא מנחת החטים קודם זאת המנחה והוא מבואר שאם הקריב מנחה קודם מנחת העומר שהיא פסולה שאפילו להדיוט לא הותר אז זה החדש ואולם אם הקריבה אחר מנחת העומר קודם זאת המנחה איננה פסולה כי לא זכרה התורה בביאור המנע זה:
@74 **ממושבותיכם תביאו לחם התנופה וגו'.** למדנו ששתי הלחם אינם באים אלא מן הארץ כי לא כלל בזה בכל מושבותיכם רק המושבו' המיוחדים ולמדנו שכל אחד משתי הלחם בא מעשרון אחד ויתבאר שהם באים מן החדש כי התורה קראה זאת המנחה מנחה חדשה:
@74 **חמץ תאפינה.** לפי שמדת העשרון יחוייב שתהיה מלאה סולת שנאמר שני עשרונים סלת למדנו שהוא מביא שאור ממקם אחר לחמצו שאם היה מודד הסלת עם השאור היתה המדה חסרה או יתרה ואם יקח מתוכה לחמצה עד שיעשה שאור הנה יהיה נפסל בלינה והנה יתבאר אחר זה איך תהיה תנופת ב' הלחם:
@74 **בכורים ליי'.** ר"ל שתהיה מנחה ראשונה לשאר המנחות שהם באים מן החטים והנה מפני זה בכורים שיובאו ליי' מראשית פרי האדמה ולזה ראוי שלא יביאו בכורים קודם שתי הלחם כי אלו הבכורי' הם שיובאו באופן שיותר שלם כמו שיתבאר מעניין שא הבכורים הם שיובאו באופן היותר שלם כמו שיתבאר מעניין שאר הבכורים עם שאלו הבכורים הם של צבור ושאר הבכורים הם של יחיד ויש לצבור קדימה על היחיד אלא מפני שנקרא העומר גם כן מנחת הבכורי' כמו שבארנו אם הביא בכוריו אחר העומר אינם פסולים ואמנם קודם זה הם פסולים כי כבר יהיה מהם מהחטים והשעורים כמו שיתבאר בעניין הבכורי' בפרשת כי תבא והם אסורין קודם מנחת העומר אפילו להדיוט:
@75 **והקרבתם על הלחם וגו'.** הנה זה הקרבן הוא בא בכלל הלחם מלבד מוסף היום הנזכר בפרשת פינחס:
@76 **ועשיתם שעיר עזים אחד לחטאת ושני כבשים לזבח השלמים.** ראוי שתדע שאלו הכבשים הם קדשי קדשים ולזה לא יהיה שחיטתם כי אם בצפון ואינם נאכלין כי אם לזכרים כשאר קדשי הקדשים כמו שנתבאר בפרשת צו ואולם יתבאר שאלו הכבשים הם קדשי קדשים לפי מה שיתבאר במה שנזכר מהם בפרשת ויקרא והנה ראוי שלא יהיו השלמים בקדושה פחות מהלחם הבא עמהם ועוד כי התורה אמרה באלו הכבשים קדש יהיו ליי' לכהן ואם לא נוספה בהם קדושה על קודשת שאר השלמים לא היתה התורה צריכה להודיע לנו שהם קדש ואמנם כונת התורה שהם קדש מבין שאר השלמים וזה מבואר מאד:
@77 **והניף הכהן אותם על לחם הבכורים תנופה לפני יי' על שני כבשים.** ר"ל שיניף הכהן הכבשים בעודם חיים ותנופתו אותם יהיה נוסף על נפתו לחם הבכורים או רצה בזה שיניפם ויניף להם הביכורים עמהם בטעם מגרשה ומשמנה על כל לבונתה ואמר על לחם הבכורים להורות שלחם הבכורים הוא העקר ואמנם מצב אלו הדברים בעת ההנפה הוא שיהיו שתי הלחם על שני הכבשים:
@77 **קדש יהיו ליי' לכהן.** ר"ל שקצתם הוא ליי' וקצם לכהן והם ליי' ולכהן במדרגת קדשי הקדשים ולזה ינהג בהם דין קדשי הקדשים כפל בכל ענייניהם. וראוי שתדע שאם לא נמצאו כבשים לא תבטל מפני זה מנחת שתי הלחם כי היא העקר לפי מה שזכרה התורה מעניינה ולזה הקדימה גם כן לזכרה קודם זכרון שני הכבשים להורות שאין לה התלות בהן אבל בלי ספק לכבשים האלו התלות בשתי הלחם כי אופן הקרבתם מתאחד עם שי הלחם כי הנפתם הוא עם שתי הלחם וכן הנפת אישי החלבים אשר להם וחזה ושוק מתאחדת עם שתי הלחם כמו שהתבאר במעט עיון ממה שנזכר בפרשת צו מתורת זבח השלמים ומזה המקום יתבאר שאם אין שם שתי הלחם לא תתכן הקרבת שני הכבשים ואולם שאר הקרבנות הנזכרים בזה המקום אף על פי שהם באין בגלל הלחם הנה אין להם התלות בו עד שיבטלו בבטולו כי לא נמצא להם קשר עם הלחם הזה באופן שיהיה להם התלות בו:
@78 **וקראתם בעצם היום הזה מקרא קדש יהיה לכם.** מגיד שקריאתו מקרא קדש מיוחסת לנו כי היא תלויה קדוש החדש שהוא מסור לב"ד וזה שאחר שקדשו ראש חדש ניסן יהיה יום הט"ו חג המצות ואחריו ימנו מ"ט יום והחמשים יום יהיה חג שבועות:
@78 **כל מלאכת עבודה לא תעשו.** היא המלאכה שאינה לצורך אוכל נפש כמו שקדם בפרשת בא אל פרעה:
@78 **חקת עולם בכל מושבותיכם לדורתיכם.** ר"ל השביתה ממלאכת עבודה ואולם הקרבנות אינם נוהגות בכל מושבות כי אם במקום אשר יבחר יי' והוא בית המקדש כמו שנתבאר במה שקדם:
@79 **ובקצרכם את קציר ארצכם וגו'.** כבר התבאר בפרשת קדושים ובא בזה המקום כי הכונה בעינה שצוה השם יתעלה שיקריב מנחת העומר ושתי הלחם מהקציר החדש להעיר כי הכל בא מהש' יתעלה והוא צוה גם כן להטיב מהם אל העניים קודם שיבא לידינו להעיר כי זה בא מהש' יתעלה והוא רצה שיזכרו עניים בזה החלק ואנחנו בשאר כי הכל בא מאתו ומאתו הכל:
@81 **בחדש השביעי באחד לחדש יהיה לכם וגו'.** ומזה המקום יתבאר שהתרועה על הצר הצורר יהיה אחריה ענוי נפש כי לזה התכלית תהיה לפי שבעשור לחדש הזה יהיה יום הכפורים כמו שנתבאר בפרשת אחרי מות הנה הקדימה התורה לעורר האנשים על התשובה והשבר חלב והכנעו מר"ה הזה והוא מבואר שהתקיעה בשופר נותנת חרדה בלב כמו שאמר אם יתקע שופר בעיר ועם לא יחרדו ובכלל הנה הקולות החזקים הם מרעידים מאד ובזה מביא להכנע הנפש הבהמית וכאלו העירנו בזה שיכנעו לבבנו ונפשפש במעשינו לתקן המעוו' בהם כדי שנהיה נכונים לכפרה ביום הכפורים וראוי שתדע כי התקיעה תהיה בזולת תרועה אמר בפשרת בהעלותך תתקעו ולא תריעו ואמנם התרועה לא תהיה בזולת תקיעה אמר שם בעניין תרועה ותקעתם תרועה תרועה יתקעו למדנו שמדרך התרועה שתהיה תקיעה לפניה ולאחריה ובכלל הנה מפני שהכונה בזה להחריד הלבבות ולעוררם על התשובה הנה רצתה התורה שיהיה זה הקול באופן שיתכן זה יותר ולזה אמר בו תרוע' וכן אמר בפרשת בהעלותך במה שהוא לזאת הכונה בעינה והרעותם בחצוצרות ונתבאר שזאת התרועה היא בשופר ממה שצותה התורה ביום הכפורים של יובל שהוא לזא' הסבה בעינה שנאמר בפרשת בהר סיני והעברת שופר תרועה בחדש השביעי וגו'. ושם נבאר בג"ה מה שיורה עליו שם השופר:
@82 **כל מלאכת עבודה לא תעשו והקרבתם אשה ליי'.** הנה המוסף הננזכר בפרשת פנחס ולמדנו מזה המקום שהפר והאיל והכבשים הנזכרים שם אינם מעכבים זה את זה שנאמר אשה ליי' מ"מ שיהיה שם אשה:
@84 **אך בעשור לחדש השביעי הזה.** כבר התבאר בפרש' אחרי מות ענין זה הענוי וזה האשה שזכר בכאן הוא מוסף הנזכר בפרש' פנחס:
@84 **ועניתם את נפשותיכם וגו'.** בארה התורה שהתחלת הענוי הזה הוא מהערב של יום התשיעי ויהיה מערב עד ערב באופן שיהיה יותר שלם זמן הענוי והשביתה מכל מלאכה ולזה אמר תשבתו שבתכם והיה זה כי ימינו הם מתחילין מן הערב מפני היותינו חושבין לחשבון הלבנה כמו שביארנו בפרשת בא אל פרעה ואף על פי שמצד השמש היה יותר ראוי שיהיה היום מתחיל מזריחת השמש כמו שיתבאר לתוכנים ולזאת הסבה גם כן היתה השנה אצלנו מתחדשת מן החדשים אשר לירח ואף על פי שאינה שנה באמת לפי השמש וכאלו היה זה מכון להעיר שאין האלהות והממשלה לשמש כמו שהיו חושבין עובדי השמש והיה חשבונינו לחשבון הכוכב אשר אי אפשר שיטעה בו אדם לראותו שנוי עניינו בכל חדש וחד שהוא הירח שיחסר אורו פעם ויוסיף פעם:
@85 **וכל מלאכה לא תעשו בעצם היום הזה כי יום כפורים הוא לכפר עליכם.** למדנו שהיום בעצמו מכפר ואף על פי שאין קרבנו קרב וראוי להיותכן כי הקרבנות אינם אלא להישירנו על התשובה ואם היושרנו אליה בזולת הקרבנות הנה מן הראוי שיכפר והנה באר בזה המקום שכבר יתחייבו על עשיית כל מלאכה בעצם היום הזה כרת וכן אם לא יתענו בעצם היום הזה ואמר והאבדתי את הנפש ההיא מקרב עמה תמורת הכרת להעיר על שכוון בכרת ובר בארנו עניינו במה שקדם והנה ביאר שהשביתה ממלאכה ביום הכפורים נוהגת בכל מושבות שנאמר כל מלאכה לא תעשו חקת עולם לדורותיכם בכל מושבותיכם וזכר אחר זה שנית חיוב הענוי להורות שהוא גם כן נוהג בכל מושבות עם שהוא מבואר בעצמו שאין לו התלות בארץ ולא בענין הקרבנות אבל אם היה אפשר היה ראוי שיחזק עניינו בבטול הקרבנות כדי שישלם לנו בזה מן ההישרה אל התשובה מה שנפקד ממנו בבטול הקרבנות מההישרה אליה:
@91 **בחמשה עשר יום לחדש השביעי וגו'.** הנה הסכות יתבאר לפי הוראת הגדר שהוא סכוך נעשה מעצים תלושים בזולת בנין והוא נעשה על הרוב מעצים שיש בהם עלים כדי שיהיו למחסה מהשמש אמר וסכה תהיה לצל יומם מחורב וכבר נאמר בספר עזרא צאו ההר והביאו עלי זית ועלי עץ שמן ועלי הדס ועלי תמרים ועלי עץ עבות לעשות סכת בכתוב ולזה הוא מבואר שזה הסכוך לא יהיה כי הם בתלוש ומבואר גם כן מצד הוראת הגדר שאינו תוך הבית שאם היה כן הנה אינו מסכך באלה אבל הבית הוא שיהיה מסך משיכנס בו השמש והיושב בו יושב בבית לא בסכות ומבואר גם כן מצד הוראת הגדר שאין הסכוך הזה נעשה מהכלים ולא מהאוכלין והנה חג הסוכות לא יתמיד כי אם שבעת ימים אולם וביום השמיני יהיה שבתון כמו שיתבאר אחר זה אך לא ישבו בסכות ואמנם שזה החג הוא ליי' כי הכונה בכל המועדים הוא לעבודתו יתעלה ולהתקרב אליו כפי היכולת כמו שיתבאר בג"ה:
@92 **ביום הראשון מקרא קודש.** כבר התבאר זה במה שקדם:
@93 **שבעת ימים תקריבו אשה ליי.** כבר נתבאר זה האשה בפרשת פנחס ומזה המקום יתבאר שהפרים והאלים והכבשים של מוסף היום אינם מעכבים קצתם קצת שנאמר אשה ליי' מ"מ ביום השמיני מקרא קדש יהיה לכם וגו'. כבר נתבאר בפרשת פינחס זה האשה והרצון באמרו עצרת הוא שיהיו נעצרים מעשיית מלאכת עבודה והם הלכות שאינם לצורך אוכל נפש:
@94 **אלה מועדי יי' וגו'.** ר"ל שאר המועדים זולת השבת כי אחר זכירתו השבת אמר אלה מועדי יי' אשר תקראו אותם במועדם וכאשר השלים המאמר בהם אמר שאלו המועדים שזכר הם המועדים שרמז אליהם בראש המאמר הזה שמיוחסת קריאתם אלינו:
@94 **עולה ומנחה.** כבר נזכר מנחת אלו העולות בפרשת פינחס. והנה העולה היא עקר והמנחה היא נמשכת לזה ולזה אין ראוי שתקריב מנחת העולה קודם העולה:
@94 **זבח ונסכים.** ידוע כי לעוה יהיו נסכים מוגבלים כמו שנתבאר בפרשת פינחס כמו שיש לה מחנחה מוגבלת ולזה ראוי שנעיין למה לא אמרה התורה עולה ומנחה ונסכים ונאמר כי ידמה שיהיה סבה בזה להורות כי הנסכים אינם מתאחדים עם העולה כהתאחדות המנחה לה כי אינם להקרבה אבל להסיר הזוהמא כמו שכתבנו ויהיה הרצון בזבח זבח השלמים כי כבר יחוייבו באלו המועדים להקריב שלמי חגיגה ושלמי שמחה כמו שיתבאר אלא שכבר יקשה לזה מפירוש מה שאמר אחר כן דבר יום ביומו והנה לא הוגבלו אלו השלמים בכל יום מאלו הימים ולזה היותר נאות שיאמר כי הרצון בזבח העולה גם כן אלא שהיא תהיה נקראת עולה מצד מה שיקטירו ממנה במזבח שהיא עולה עליו בכלליו ונקראת זבח מצד מה שיקטירו ממנה במזבח שהיא עולה עליו בכללות ונקראת זבח מצד הזביחה אשר בו יוקח דמה לזרוק על המזבח והוא מבואר שהמנחה מתאחדת עם הנקטר מהעולה והנסכים עם דמה הנשפך אל יסוד המזבח כי לזאת הסבה היו ולהורות על זה קראה התורה בשני אלו השמות מתחלפי' עם המנחה והנסכים':
@94 **דבר יום ביומו.** למדנוח מזה שקרבנות היום הם תמידין ומוספין אין להם תשלומין למחר:
@95 **מלבד שבתות יי'.** למדנו מזה שאלו הקרבנות יקריבו בכל יום מאלו מלבד הקרבנות המוגבלים בשבת והם מוסף שבת שאם היה שבת באחד מאלו הימים הנה יקריבו בו יותר על אלו הקרבנות המיוחדים לשבת:
@95 **מלבד מתנותיכם.** אחשוב שירמוז בזה מה שיתנו ליי' בזולת דר או נדבה כמו מעשר הבהמה ובכורות:
@95 **ומלבד כל נדריכם ומלבד כל נדבותיכם אשר תתנו לה'.** הקרבנות הבאים בנדר או נדבה כמו העולה והשלמים והמנחה ולמדנו מזה שכל קרבנות יחיד קרבים ביום טוב וידמה שהעולה שאן זמנה מוגבל ביום ההוא כמו עולת יחיד אינה רוחה יום טוב כי לא יעשה ביום טוב רק מה שהגבילה אותו התור' אם אינו לצורך אוכל נפש ואמנם השלמי' ומה שידמה להם יקריבו ביום טוב כי הם צורך אוכל נפש ואולם בחולו של מועד יקריבו כל הקרבנות:
@96 **אך בחמשה עשר יום לחדש השביעי באספכם את תבואת הארץ תחוגו את חג יי' שבעת ימים וגומ'.** ביאר בזה כי סבת זה החג מפני שאז אסף כל אחד ממנו תבואתו מגרנו ומיקבו כדי שיכיר בו כי הכל בא לו מה' ית' ולזה באה זאת המצוה:
@96 **תחוגו את חג יי' שבעת ימים.** כבר ביארנו במה שקדם כי זאת החגיגה היא זביחת שלמים ולזה תמצא שאמ' משה ויחוגו לי במדבר תמורת הזביחה כמו שזכרנו במה שקדם ואמר שבעת ימים ואם היא בחמשה עשר ימים לחדש השביעי כמו שזכרנו להורות שזאת החגיגה יש לה תשלומין כל שבעה:
@96 **ביום הראשון שבתון וביום השמיני שבתון.** ר"ל ביום השמיני לראשון שזכר כי בכל אחד מאלו שני הימים צוונו לשבות ממלאכה:
@97 **ולקחתם לכם ביום הראשון פרי עץ הדר כפות תמרים וענף עץ עבות וערבי נחל.** לפי שאין זאת המצוה כי אם ביום הראשון לפי זה המאמר ובסוף אמר שהוא ששבעה ימים למדנו שאמרו ולקחתם לכם ירצה בו כשלא תהיו לפני יי' והוא כשיהיו חוץ לבית המקדש ואמנם לפני יי' אלהים והוא בבית המקדש תהיה זאת המצוה שבעת ימים ולפי שאמר ולקחתם לכם ביום הראשון למדנו שאין אדם יוצא באלו הדברים שזכר אחר זה אם לא היו שלו ולזה הוצרכה התורה לאמור לכם. פרי עץ הדר כפות תמרים וגו'. יורה מצד הוראת הגדר באמרו פרי עץ הדר אל האתרוג וזכרה אותו התורה בזה הלשון להורות כי היא בחרה בו מצד שהוא הדר ולזה לא נצא אם לא היה הדר ומזה המקו' יתבאר ששאר הדברים הנלוים עמו יחוייב בכל אחד מהם ג"כ שיהיה הדר וזה מבואר מהשרשים הכוללים:
@97 **כפות תמרים.** הוא הלולב והוא נקרא בזה השם מצד מה שהתמידו עליו להחזיק קצת בקצת כמו הכף שמחזיק במה שמקיף בו אמנם אחר שיתפרדו עליו כאן ולכאן איננו נקרא בזה השם גם איננו אז הדר ולזה הוא פסול:
@97 **וענף עץ עבות.** הוא ההדס שהוא עבות ר"ל שיש לו עלים רבים מקיפים בו יוצאים ממקום אחד והמעט שיפול בו זה השם הוא כשהיו לו שלשה עלין מקיפין בו יוצאים בגבעול אחד ואולם אם יצאו שנים שנים אין זה עבות וזה מבואר מצד הוראת הגדר:
@97 **וערבי נחל.** הוא מין מן הצמחים גדל על הרוב בנחלים ולזה קראה אותו התורה ערבי נחל לא שתקפיד שיהיה גדל על נחל כי היא אמנם תקפיד על המין שילקח ממנו והנה הנקרא ערבי נחל הוא צמח שעלה שלו משוך ופיו חלק וקנה שלו אדום וממנו ימצא שבפי עלהו פגימות דקות מאד מאד וקטנות ואולם מה שעלה שלו עגול ופיו דומה למגל אינו נקר' עבי נחל ואיננו כשר וראוי שתדע כי מפני שאמר כפות תמרים וענף עץ עבות וערבי נחל הנה מן הראוי שיהיו שלשה אלו המינים יחד ועם כל זה אם לקחן אחד אחד יצא שהרי לקחה כלם ואמנם האתרוג ילקח לבדו ולזה לא אמרה תורה פרי עץ הדר וכפות תמרים והנה יקרא הלולב האחד כפות תמרים מצד עליו שבהם יתהוו התמרים ואולם מה שאמרה התור' וענף עץ עבות ידמה שהרצון בו ענף ועץ ר"ל שאין מתנאיו שיהיה ענף אבל יהיה מותר אע"פ שהו' העץ בכללו והנה זה אפשר בזה הצמח לקטנו ואפשר שיובן מזה ג"כ שילקח מזה הצמח ענף ועץ באופן שיהיה עבות מצד רבוי עליו ורבוי ענפיו ולזה ילקחו שלשה כדי הדס כי כבר יקרה בזה הצמח שלא יהיו בו יותר משלשה ענפים ולזה ילקח העץ בהלקחם ולפי שאמר וערבי נחל שרומז אל רבוי והפחות שיפול בו זה השם הוא שני הנה ילקח שני בדי ערבה. וידמה והוא הנכון שהרצון בזה שיקח ענף עץ עבות וערבי נחל ולזה לא יתחייב לקחת מכל אחד מהם כי אם בד אחד והוא מבואר שהלקיחה הנהוגה בהם הוא שילקחו דרך גדלתם ולזה אם לקחם של כדרך גדלם לא יצא כי התורה תצוה ענינם באופן הנהוג מהן כמו שהתבאר מהשרשים הכוללים וכאלו שב זה אל מה שהוא מחוייב מצד הוראת הגדר. וראוי שתדע שאלו המינים הארבעה מעכבין זה את זה כי התורה צותה שנקח אלו המינים כלם ולפי שהאתרוג יהיה לבדו ושאר המינים הם יחד הנה ראוי שילקחו בימין הג' מינין והאתרוג בשמאל:
@97 **ושמחתם לפני יי' אלהיכם שבעה ימים.** ירצה בזה שישמחו שם במקדש שבעה ימים בלקיחת אלו הארבעה מינין ובכל מיני השמחה ויתבאר שזאת השמחה אינה דוחה יום טוב וכל שכן שבת לפי שהתורה אמרה כי ביום הראשון לא ישמחו כי אם בלקיחת אלו הארבעה מינין אך בשאר מיני שמחות שיהיה בהם מה שלא יתכן העשותו וביום טוב לא יותר להם לשמוח והנה תכלול ג"כ זאת השמחה זביחת שלמים והם הנקראים שלמי חגיגה שנאמ' וזבחת שלמים וכלת שם ושמחת לפני יי' אלהיך ומזה המקום יבאר שאין שמחה זו אלא בבשר בהמה לא בבשר העוף כי השלמים אינם באים כי אם מהבהמה:
@98 **וחגותם** אותו חג ליי' שבעת ימים בשנה. הנה אמרו אותו שב אל היום הראשון שזכר בפסוק הקודם ואמר שבעת ימים בשנה להורות שיש לחגיגה זו תשלומין כל שבעה ואמר בשנה לפי מה שאחשוב להורות שאין חגיגת יום זה משתלמת בחג הסוכות של שנה אחרת:
@98 **חקת עולם לדורותיכם בחדש השביעי תחוגו אותו.** באר שזו המצוה נוהגת לדורות:
@99 **בסכות תשבו שבעת ימים כל האזרח בישראל ישבו בסכות.** צוה שנשב ז' ימים בסוכות באופן שבתנו בבית ולזה יחוייב שנאכל ונישן שם כי באלו העניני' נשתמש מהבית ולפי שזאת הישיבה מתיחסת לישיבה בבית והיא תמורתה והישיבה בבית להנאה לא צער הנה כשתהיה הישיבה בסכה בצער לא יתחייב לישב בסוכה ועוד שכבר חוייבנו לשמוח באלו השבעה ימים ולזה ראוי שיעזוב כל דבר שמצער שמבלבל השמחה ומזה המקום יתבאר שאם ירדו גשמים יצטערו בהם בשתם אז בסכה הנה יהיו הבעלים פטורים מהישיבה אז בסכה ולפי שהסכה היא אהל מה והיה מגדר האהל שיהיו לו שלשה דפנות האחד לאחריו והאחד בצד הימין והאחד בצד השמאלי והוא מבואר בנפשו מענין האהלים שיעשו מוכרי המסחרים הנה יספיק בסכה שיהיו לו שלשה דפנות ומזה ג"כ יתבאר שהדופן השלישי הוא שיהיה לו שיעור מעט כי כן דרך האהלים ולפי שאהל לא יקרא אהל אלא אם היה לו גג טפח הנה יחוייב בסכה שיהיה לה גג טפח ולפי שזה האהל הוא תמורת הבית שהוא עשוי לשבת האדם בו הנה לא יהיה גבהו פחות מעשרה טפחים כי גובה האדם הבינוני בהיותו יושב הוא זה השעור והוא המצב היותר מיוחד שיהיה לו בשבתו בבית ולפי שזה האהל עשוי לאכול בו הנה יחוייב שיהיה באופן שיחזיק ראשו ורובו ושלחנו וזה השיעור יהיה על המעט ז' טפחים על ז' טפחים והוא מבואר שהיושב בסכה שתחת הסכה אינו יושב בסכה שהוא רואה בהיות אותו בתוכה כי אינה מסככת עלו על דרך האמת והוא אינו יושב ג"כ בסכה העליונה כי הוא אינו רואה באוירה ולזה אינו יוצא ידי סכה וכ"ש אם היתה הסכה תחת הבית או תחת האילן:
@99 **כל האזרח בישראל ישבו בסכות.** אין ראוי שנלמוד מזה שלא תהיה זאת המצוה נוהגת בגר צדק כי דין הגר במצות התוריות כדין כל ישראל כמו שהתבאר ממקומות רבים מהתורה ואמנם זכר האזרח כי יחשב שיהיו קצת האזרחים פטורים מזאת המצוה והם השרים אשר לגודל מעלתם לא יאות להם לשבת בסכות כי אם בהיכלות יפות ושלמי הבניין באופן שיהיו חזקים מאד ולזה בארה התורה שדין כל האזרחים שוה בזאת המצוה:
@100 **למען ידעו דורותיכם כי בסכות הושבתי את בני ישראל בהוציאי אותם מארץ מצרים.** זה זכר אל המופת הנפלא שעשה הש' ית' לישראל בהוציאו אותם מארץ מצרים שהיה עננו עומד למסך שנאמ' ועננך עומד עליהם ולפי שזאת המצוה היא למען ידעו בעבור זה הפלא שעשה הש' יתע' אז לישראל הנה ראוי שיהיה זאת הסכה באופן שישלוט בה העין ולזה ראוי שלא תהיה גבוהה מכ' אמה:
@101 **וידבר משה את מועדי יי' וגו'.** ר"ל שכבר השלים מה שצוהו הש' ית' שידבר אל בני ישראל כמו שכתוב בראש העניין:
@103 **צו את בני ישראל ויקחו אליך שמן זית זך כתית למאור.** הנה התנה בשמן המאור והוא אשר ישימו במנורה שיהיה שמן זית לא שמן שאר הדברים שיעשו מהם שמן כגון האגוזים והשומשמין ומה שידמה להם ואמר זך כתית להורות שזה השמן יוציא מהזית על צד הכתישה מבלי טעינה בקורה כי השמן הזה הוא היותר זך בלי ספק וכבר יתבאר לך זה מהיין שיצא מהענבים אחר סחיטתן מעצמו כי הוא היותר נבחר מאד מהיין שיצא אחר זה מהם עם הטעינה בקורה כי כבר יתערב עמו טבע השמרים שיצא מהם וזה מבואר מן החוש ולפי שלא התנה שיהיה כתית כי אם למאור למדנו ששאר השמנים שיצאו מן הזית אחר השמן הנזכר כלם כשרין למנחות ולזה לא התנה דבר במנחות אבל אמר בשמן והוא מבואר ממה שנזכר במנחות בפרשת ויקרא ובזאת הפרשה ובפרשת פינחס ואף על פי שכבר נאמר שם במנחות תמיד של שחר בשמן כתית ונאמר ג"כ בפרשת ואתה תצוה הנה הוא למצוה לא לעכב ויעיד על זה מה שאמר בכאן כתית למאור הורה שלא יוצרכו לקחת שמן זית זך כתית כי אם למאור לא למנחות ועוד כי כבר תמצא כי כשנזכרו המנחות בכללם בפרשת שלח לך שלא הותנה בהן שיהיה השמן כתית. וכן תמצא במנחות הנזכרות בפרשת ויקרא שלא נזכר שם כי אם שמן ולא הותנה בו שיהיה כתית להעלות נר תמיד למדנו מזה שכבר תחוייב שתהיה זאת ההדלקה באופן שיעלה השלהבת תמיד ולזה היה מתנאי השמן שיהיה זך בזה האופן כי כל מה שיהיה יותר זך יהיה יותר אמתי בהעלת השלהבת ומזה המקו' יתבאר שהפתילה יחוייב ג"כ שתהיה באופן שיתכן שתעלה נר בקלות והוא מה שאמר להעלות נר תמיד מעיר שזאת המצוה דוחה את השבת כי לה זמן קבוע בכל יום והנה ידליקו המנורה בערב ובבקר כמו שביארנו בפרשת ואתה תצוה ושם פירשנו זה הפסוק ופסוק הבא אחריו וראוי שתדע כי עריכת המנורה יחוייב שיהיה לפני יי' ולזה ראוי שיהיה פני המנורה לצד המערה ושלא יערוך הכהן המנורה בחוץ ואחר כך יביאה בפנים אבל יחוייב שידליקה בפנים:
@105 **על המנורה הטהור' יערוך את הנרות לפני יי' תמיד.** למדנו שאין ראוי שיהיה דבר מפסיק בין הפתילה והמנורה כאלו תאמר צרור או קיסם אבל יחוייב שתהיה הפתילה בגוף המנורה:
@106 **ולקחת סלת ואפית אותם שתים עשרה חלות שני עשרונים יהיה החלה האחת.** הנה מפני שהסלת מורה על הקמח היותר דק והיותר לבן הנה נמשך לזה לכונת התורה לדקדק בענין שיהיה בתכלית היופי והדקות ולזאת הסבה בעינה דקדקה בחטים שיהיו נבחרים ושתתוקן בהם המלאכה בתכלית מה שאפשר באופן שתהיה הסלת יותר נקי וזה כולל לכל המקומות שנזכר בהם סלת והוא מבואר שאפיות אלו החלות הוא בעזרה וכן לישתו ועריכתם לאפות אותן וזה שאפילו בקדשים שנפסלו דקדקה התורה שלא ישדפו חוץ לעזרה כמו שנתבאר בהפרשה צו כ"ש שתדקדק באפייתן ובבושלן. ומזה המקום יתבאר שכן העניין בשאר המנחות כי הם כלם קדש קדשים:
@106 **שני עשרונים יהיה החלה האחת.** למדנו שלישת כל חלה וחלה בפני עצמה כדי שיהיו בכל אחת מהם שני עשרונים ולפי שזאת המדידה תהיה בעשרון שבמקדש הנה הכלי מקדש הסלת ויפסל אם יצא חוץ לעזרה ולזה יתחייב מזה הצד גם כן שתהיה לישתה ואפייתה בעזרה. ולפי שזה הלחם הוא לחם הפנים שהוא בתמונה שלא יתכן שיאפה בזולת שבירה ובזולת קלקול תמונתו אם לא היה נאפה בדפוס היו שם דפוסים של זהב היה נאפה בהם כמו שנזכר בפרשת תרומה והנ היה מחוייב לזאת הסבה שיהיה שם דפים ישימו בתוכה החלה כשהיא בצק ודפוס אחר מבפנים לשמור הבצק שלא תתקלקל תמונתו ובהן היה נאפה בתנור כל צרכו ואחרי כן יסירוה תחלה מאלו הדפוסי' שלא יקלקלוה חום הדפוסים וישרפוה לדקותה ולפי שהיא רכה עדיין בצאתה מן התנור הנה היו משימים אותה בדפוס צונן עד שתצטנן ותתחזק ולפי שהחום מועט יספיק לאפיית אלו החלות לדקותם הנה היה ראוי שיאפו בתנור קטן כדי שלא ישרפו ולא היה נאפה בשבת כי התורה לא חייבה שיהיה נעשה בשבת כי אם עריכת המערכת שנאמר ביום השבת יעריכנו לפני ה' תמיד. וכבר ביארנו בפרשה ויקחו לי תרומה זאת העריכה איך תהיה:
@107 **ושמת אותם שתים מערכות שש המערכת.** ר"ל ששה חלות תהיה המערכה מאלו המערכות באופן שיהיו שתים עשרה חלות בשתיהן:
@107 **על השלחן הטהור לפני ה'.** למדנו שאין הבדל בין החלה והשלחן אבל היא על שטח השלחן ואמנם בין החלות תהיינה המנקיות כמו שביארנו בפרש' ויקחו לי תרומה ולמדנו ממה שאמר לפני ה' שפני עורך אלו המערכות יחוייב שיהיו לפני ה' שהוא לצד המערבי ששם קדש הקדשים:
@108 **ונתת על המערכת לבונה זכה.** ר"ל אצל כל מערכת של אלו המערכות ישים לבונה זכה בכף אחת והם הכפות הנזכרות בפרשת תרומה:
@108 **והיתה ללחם לאזכרה וגומ'.** רוצה לומר שהלבונה תהיה ללחם לאזכרה כשיקטירנה להש' על מזבח העולה וזאת ההקטרה תתיר הלחם לכהנים כמו שיתיר הקומץ והלבונה שירי המנחה והיא תהיה נאכלת אחר זה לזכרי כהונה לבד לפנים מן הקלעים כמו שאמר אחר זה:
@109 **ביום השבת ביום השבת יערכנו לפני יי' תמיד מאת בני ישראל ברית עולם.** כבר נתבאר הסבה בעריכתה ביום השבת בפרשת תרומה ולפי שיחוייב שיהיה זה הלחם על השלחן תמיד חוייב שיהיו שם כהני' כבים אלו מושכין הלחם מעל השלחן ואלו מניחים הלחם שם בעת שהאחרים מושכים באופן שלא ימנע השלחן מזה הלחם כלל והנה יסירו כפות הלבונה משם ויקטירם בשבת להתיר הלחם לכהנים וישימו שם לבונה אחרת אצל המערכת כמשפט הראשון וזהו תמיד ויחוייב שישים אצל כל מערכת לבונה ביום השבת שסדר המערכת כי כבר ביאר כי מעניין המערכה שתחוייב להעשות בשבת יהיה נתינת הלבונה אצל המערכת ולזה זכר כל זה קודם שצוה שתעשה המערכת בשבת לפי שכבר אמר והיתה ללחם לאזכרה למדנו שבעת שהלבונה ראוי לאזכרה יחוייב שיהיה הלחם על עניינו רוצה לומר כל חלה שלמה לזה אם נפרסה חלה מן החלות בעוד שהלחם על השלחן לפי הראוי הנה הלחם פסול ואינו מקטיר עליו הלבונה שנאמר ללחם והוא לח המערכה שנערך על השלחן ומזה המקום יתבאר שאם אחר שהוסר הלחם מעל השלחן נפרסה חלה מהחלות או אחר שהגיע העת להסירו כי אז אינו לחם המערכה לפיכך הנה אף על פי שהוא פסול הנה יקטיר עליו הלבונה כי כבר היתה ללחם מה שהתמידה להיות אצלו לפי הראוי והיתה לאהרן ולבניו רוצה לומר אחר העשות מה שזכר והוא שיקטירו הלבונה להתיר הלחם לכהנים והגיד שאהרן קודם לבניו ולזה יהיה כהן גדול נוטל חלק בראש. ואכלוהו במקום קדוש. הוא לפנים מן הקלעים כמשפט קדשי הקדשים לפי מה שנתבאר בפרשת צו ואמרו ואכלוהו שם ללחם שזכר:
@111 **ויצא בן אשה ישראלית.** לא נתבאר לנו מן התורה על מה היו נצים והוא מבואר כי כבר יקרה זה לסבות רבות ואמנם רבותיי' אמרו כי הם היו נצים לפי ששבטו של דן לא היו מניחים אותו לעמוד ביניהם לפי שנ' איש על דגלו באותות לבית אבותם:
@112 **ויקוב בן אשה הישראלית את יי'.** רוצה לומר שכבר פירש השם המפורש וקלל אותו באופן הנהוג לקלל והוא בשם מהשמות המיוחדים לשם יתעלה כאלו תאמר שקלל שם בשם כמו שאמר יכה יוסי את יוסי והנה הביאוהו השומעים אל משה לבאר להם משפטו על פי השם והניחוהו במשמר עד שיבאר להם זה:
@115 **הוצא את המקלל מחוץ למחנה וסמכו כל השומעים את ידיהם על ראשו ורגמו אותו כל העדה.** למדנו שממתה מחוץ למחנה ולזה יחוייב שתהיה חוץ לב"ד ורחוק מהם עם שכזה תועלת שאם ימצא לו בין זה הזמן מי שידע לו זכות יחזירוהו והנה זאת הסמיכה היתה כאלו אמרו שהם נקיים מהחטא הזה בהמיתם אותו לפי שהוא היתה סבת מיתתו ולזה אומרי' לו בסמכם ידיהם על ראשו דמך בראך שאתה גרמת לך והנה העדים הם אשר תהיה ידם בו בראשונה להמיתו כמו שזכרנו במה שקדם ואמנם ורגמו אותו כל העדה שאם לא מת על ידי העדים כל העדה רוגמים אותו באבנים:
@116 **ואל בני ישראל תדבר לאמר איש כי יקלל אלהיו וגומר.** למדנו מזה שהמקלל הוא בכרת וכבר התבאר זה בפרשת בהעלותך ולזה אם לא היו שם עדים והתראה יתחייב כרת ואם היו שם עדים והתראה וקללו בשם מהשמות המיוחדים לשם יתעלה כמו אל אלהים שדי צבאות ומה שידמה להן הנה יהיה נסקל כמו שהתבאר פסוק הבא אחר זה והוצרכה התורה לכפול המאמר בה שלא נחשוב שיהיה מה שגזר על המקלל ההוא הוראת שעה ולא ינהג דין זה בכל מקלל:
@118 **ואיש כי יכה כל נפש אדם מות יומת.** כבר נתבאר בפרשת מפשטים שה הדין הוא בהורג אחד מאנשי התורה ושם נתבאר שזאת המיתה היא בסייף:
@119 **ומכה נפש בהמה ישלמנה וגו'.** רוצה לומר שישלם לו בהמה השוה לה או שוויה כי הכסף דינו כדין שוה כסף בכמו אלו הדברים כמו שזכרנו בפרשת משפטים ולהוסיף ביאור שהחובל בחברו יתחייב ממון לא שיעשה מום בו כאשר עשה בחברו כמו שאפשר יובן מלשון התורה זכרה התורה דין נתינת האדם מום בעמיתו אחר זכרה דין מכה בהמה שיתחייב ממון והנה לזאת הסבה גם כן שבה התורה להזכיר אחר כך שמכה בהמה הוא חייב בתשלומין להורות שמה שזכרה התורה בדין נותן מום בעמיתו הוא תשלומי ממון ואחר זה שב להזכיר שמכה אדם הוא חייב מיתה. וכבר ביארנו זה באופן שלם בפרשת משפטים ושם ביארנו האופן אשר ישוער בו מה שיתחייב החובל בחבירו לשלם לו מהממון:
@123 **משפט אחד יהיה לכם כגר כאזרח יהיה.** למדנו שהדין בזה שוה בגר צדק ובאיש מישראל וכבר נכפל זה במקומות רבים בתורה וראוי היה להיות כן כי התורה נימוס אחד יכוין בו לתכלית אחד במספר ומה שזה דרכו הוא בלתי מתחלק לזה יחוייב לגר שיקבל עליו כל מצות התורה בשלמות:
@124 **וידבר משה אל בני ישראל ויוציאו את המקלל אל מחוץ למחנה.** למדנו מזה שאין הדיינים יוצאים אחר מי שנתחייב מיתה בצאתו למות כי משה היה הדיין בזה והוא צוה לישראל שיוציאוהו חוץ למחנה וירגמו אותו אבן אך הוא לא יצא עמם לפי מה שיראה מזה. ובכאן נשלם זה הביאור במה שכללה אותו זאת הפרשה:

@1 **התועלת** הראשון הוא במצות והוא שלא יטמא אחד מהכהנים למת זולתי לקרוביו הנזכרים בזאת הפרשה ולא כהן גדול למת אפילו היה מקרוביו וכבר התבאר התועלת המגיע מזאת האזהרה במה שקדם:
@1 **התועלת** השני הוא במצות והוא האזהרה מקרוח הכהנים קרחה בראשם למת ומשרוט בשרם שריטה לנפש וזה מדרכי האמוריים ובר התבארו התורה באלו האזהרות במה שקדם:
@1 **התועלת** השלישי הוא במצות והוא האזהרה מלגלח הכהנים פאת זקנם וכבר נתבאר התועלת המגיע מזאת האזהרה במה שקדם בזאת הפרשה:
@1 **התועלת** הרביעי הוא במצות והוא שלא יקח אחד מהכהנים אשה זונה וחללה וגרושה ולא כהן גדול אלמנה כי אם בתולה מעמיו וכבר התבאר התועלת המגיע מאלו המצות אצל המאמר בהם:
@1 **התועלת** החמישי הוא במצות והוא שנדין בשרפה בת כהן שתהיה אשת איש שזנתה התועלת מבואר בזאת המצוה:
@1 **התועלת** הששי הוא במצות והוא האזהרה שלא יפרע כהן גדול ראשו בעת מהעתים ושלא יפרום בגדיו כי הוא היה תמיד במקדש ולזה ראוי שיהיה תמיד ראוי לעבודה וכבר התבאר התועלת המגיע מאלו האזהרות בפרשת ויהיה ביום השמיני:
@1 **התועלת** השביעי הוא במצות והוא האזהרה שלא יניח כהן גדול עבודתו מפני אנינותו על מות אחד מקרוביו כי הוא בלתי מחלל עבודתו בזה והתועלת בזאת האזהרה הוא להעיר שאין ראוי לשלם שיכאיב לבו מאד על כמו אלו העניינים כי אין בהכאבת לבו תועלת כלל ולא יוכל להשיב מה שהיה ולזה לא יניח עבודתו כהן גדול מפני האנינות כי לגודל מעלתו הוא בלתי מתפעל באלו המקרים באופן שיבלבל כונתו אשר בזאת העבודה הנכבדת לשם יתע' ואין ראוי גם כן שלא יתן אל לבו זה הענין כלל ולזה לא יתכן לו שיאכל קדשים באנינות כמו שהתבאר בפרשת שמיני כי אם תביאהו עוצם אהבתו השם יתע' לבלתי תת לבו כלל באנינות בעת שמושו במקדש הנה בעת אכל ולא יוכל על זה כי ראוי שיתן החי אל לבו אלו הענינים וידאג דאגה מה במיתת קרוביו כמו שביארנו בענין ספוד אברהם לשרה ובכותו עליה לזאת הסבה נמנעו שאר הכהנים מלשמש באנינות כמו שהתבאר מזה המקום:
@1 **התועלת** השמיני הוא במצות והוא שלא יקרב כהן גדל בעל מום לעבודה ולא יבא אל הפרוכת ואל המזבח לא יגש ואף על פי שלא עבד וכבר התבא' התועלת המגיע מאלו האזהרות אצל המאמר בהם:
@1 **התועלת** התשיעי הוא במצות והוא האזהרה שלא יקרב כהן בלתי טהור לעבודה ושלא יאכל כהן טמא קדשים על מדרגותיהם רוצה לומר שלא יאכל תרומה אפילו טבל אם לא העריב שמשו ולא יאכל קדש אפילו העריב שמשו אם לא הביא כפרתו וכבר בארנו התועלת המגיע מאלו האזהרות אצל המאמר בהם:
@1 **התועלת** העשירי הוא במצות והוא אזהרה שלא יאכל זר קדש ולא תרומה אלא אם כן היה קנין כספו של כהן כמו עבדו הכנעני או אשתו או בהמתו וכן תאכל בתרומה בתו אם לא היתה לזר או אפילו אם היתה לזר ומת וזרע אין לה והתועלת באלו המצות מבואר:
@1 **התועלת** הי"א הוא במצות והוא לבאר דין זר אוכל בתרומ' בשגגה והתועלת בזאת המצוה מבואר:
@1 **התועלת** הי"ב הוא במצות והוא האזהרה שלא להקדיש בעל מום למזבח ושלא לזרוק דמו על המזבח ושלא להקטיר ממנו אשה על המזבח והתועלת באלו המצות מבואר מדברנו בהם:
@1 **התועלת** הי"ג הוא במצות והוא האזהרה שלא להשחית כלי הולדה מאיזה שיהיה מהבעל חי וכבר ביארנו התועלת המגיע מזאת האזהרה במה שקד' מזאת הפרשה:
@1 **התועלת** הי"ד הוא במצות והוא לבאר הבלתי ראוי לקבל מהבלתי בעל מום כמו הכלאים ויוצא דופן והיתום אשר הוא מבן שמנה ימים וכבר ביארנו הסבה בזה אצל ביאורנו לזאת המצוה:
@1 **התועלת** הט"ו הוא במצות והוא האזהרה שלא לשחוט אותו ואת בנו ביום אחד וכבר ביארנו סבת זה במה שקדם:
@1 **התועלת** הי"ו הוא במצות והוא האזהרה שלא לחלל את השם הנכבד לעבור על מצותיו על צד המרד בו אבל ראוי שימסור עצמו למיתה אם כריחו בזה מכריח לבזות השם יתעלה כמו שהתפרסם מהאומות שגזרו שמד על ישראל וזאת היא המצוה שצונו לקדש שמו ברבים והנה התועלת באלו המצות מבואר כי בזה האופן תשאר התורה קיימת תמיד ולולי זה היה אפשר שתסור ממנו לרוב שונאים הקמים עליה יסור ממנה בסורה זה הטב הנפלא המגיע מהתורה אשר אין לשאר הטובות יחס אליו כלל:
@1 **התועלת** הי"ז הוא במצות הם המצות באו בעניין המועדים בכללם וכבר ביארנו התועלת המגיע מהם במה שקדם:
@1 **התועלת** השמנה עשרה הוא במצות והוא להודיע דין המברך את השם והנה התועלת בזאת המצוה הוא מבואר בנפשו:
